window.QB_TKP_B6 = [
{id:"TKP-721", q:"Anda petugas pendaftaran puskesmas. Seorang pasien BPJS datang berobat dengan kartu yang ternyata nonaktif karena tunggakan iuran, padahal ia tampak kesakitan. Antrean pasien lain menunggu. Tindakan yang paling tepat adalah ....", opts:[{t:"Memeriksakan pasien terlebih dahulu sesuai prosedur darurat, lalu menjelaskan dengan ramah cara mengaktifkan kembali kartunya", s:5},{t:"Melayani pasien sebagai pasien umum sambil menjelaskan status kartunya dan opsi pembayarannya", s:4},{t:"Meminta pasien menunggu sambil menghubungi petugas BPJS untuk memastikan status kepesertaannya", s:3},{t:"Menolak melayani sampai pasien melunasi tunggakannya di kantor BPJS", s:2},{t:"Menyuruh pasien pulang dan kembali setelah kartunya aktif", s:1}], ex:"Pelayanan kesehatan mengutamakan keselamatan pasien; mengobati dulu lalu membantu menyelesaikan administrasi adalah sikap paling profesional."},
{id:"TKP-722", q:"Anda perawat di IGD RSUD. Keluarga pasien gawat darurat marah-marah karena merasa pasiennya tidak segera ditangani, padahal tim sedang menstabilkan pasien lain yang lebih kritis. Sikap Anda ....", opts:[{t:"Menjelaskan dengan tenang sistem triase prioritas kegawatan dan memastikan keluarga tahu pasiennya tetap dalam pemantauan", s:5},{t:"Meminta keluarga menunggu di ruang tunggu sambil berjanji segera memberi kabar perkembangan", s:4},{t:"Memanggil satpam agar keluarga yang marah tidak mengganggu pelayanan", s:3},{t:"Membiarkan keluarga marah karena memang prosedur rumah sakit tidak bisa diganggu gugat", s:2},{t:"Membentak balik keluarga tersebut agar tertib dan tidak mengganggu", s:1}], ex:"Komunikasi empatik tentang sistem triase meredakan emosi sekaligus menjaga kepercayaan pada profesionalisme layanan."},
{id:"TKP-723", q:"Anda bidan di puskesmas. Seorang ibu hamil menolak dirujuk ke RSUD meski kehamilannya berisiko tinggi, karena takut biaya dan jauh dari rumah. Yang Anda lakukan ....", opts:[{t:"Menjelaskan risiko medisnya secara jujur dengan bahasa sederhana, menawarkan pendampingan rujukan dan menginformasikan skema pembiayaan yang menanggungnya", s:5},{t:"Meminta suami atau keluarganya membantu membujuk ibu tersebut agar mau dirujuk", s:4},{t:"Mencatat penolakannya pada formulir dan memintanya menandatangani surat pernyataan", s:3},{t:"Membiarkan keputusannya karena itu hak pasien dan tidak memaksa", s:2},{t:"Mengancam akan dilaporkan jika terjadi sesuatu pada bayinya", s:1}], ex:"Edukasi persuasif plus solusi konkret atas kekhawatiran pasien adalah bentuk pelayanan yang berorientasi pada keselamatan ibu dan bayi."},
{id:"TKP-724", q:"Anda apoteker puskesmas. Stok obat program (misal obat TB) habis sementara pasien datang mengambil jatah bulanannya dan ia tinggal jauh. Sikap yang tepat ....", opts:[{t:"Menghubungi puskesmas/RS terdekat yang masih punya stok untuk merujuk pasien hari itu juga, dan mencatat agar pengadaan berikutnya diperbaiki", s:5},{t:"Memberi obat pengganti yang tersedia sambil menjelaskan kepada pasien dan dokter", s:4},{t:"Meminta pasien kembali minggu depan dengan harapan stok sudah datang", s:3},{t:"Menyarankan pasien membeli obat di apotek swasta dengan biaya sendiri", s:2},{t:"Menyuruh pasien menunggu tanpa kepastian kapan obat tersedia", s:1}], ex:"Proaktif mencari solusi lintas fasilitas menjaga keberlangsungan pengobatan pasien, terutama untuk penyakit menular seperti TB."},
{id:"TKP-725", q:"Anda petugas loket RSUD. Pasien lansia tanpa pendamping kebingungan mengisi formulir dan antre di loket yang salah. Tindakan Anda ....", opts:[{t:"Keluar dari loket sejenak membantu mengisi formulirnya dan mengantarnya ke loket/antrean yang benar", s:5},{t:"Memanggilkan petugas customer service untuk mendampingi pasien tersebut", s:4},{t:"Menjelaskan dari balik loket dengan suara keras agar ia paham", s:3},{t:"Memintanya bertanya kepada pasien lain yang sedang antre", s:2},{t:"Mengabaikannya karena antrean loket Anda masih panjang", s:1}], ex:"Pelayanan ramah-lansia menuntut inisiatif membantu langsung, bukan sekadar memberi petunjuk dari balik loket."},
{id:"TKP-726", q:"Anda dokter puskesmas. Pasien memaksa meminta surat rujukan ke RS besar padahal menurut pemeriksaan kondisinya cukup ditangani di puskesmas dan tidak memenuhi kriteria rujukan. Sikap Anda ....", opts:[{t:"Menjelaskan kriteria rujukan berjenjang dengan sabar, meyakinkan pasien bahwa penanganannya di puskesmas sudah memadai, dan menawarkan kontrol ulang terjadwal", s:5},{t:"Menolak dengan sopan dan menjelaskan bahwa kondisinya belum memenuhi kriteria rujukan berjenjang", s:4},{t:"Memberikan rujukan agar pasien tidak kecewa dan tidak protes", s:3},{t:"Menyuruh pasien mencari rumah sakit sendiri tanpa surat rujukan", s:2},{t:"Memberi rujukan dengan diagnosis yang dilebih-lebihkan agar lolos verifikasi", s:1}], ex:"Menegakkan sistem rujukan berjenjang dengan edukasi yang baik melindungi pasien sekaligus menjaga integritas layanan."},
{id:"TKP-727", q:"Anda petugas posyandu. Seorang ibu menolak bayinya diimunisasi karena termakan isu hoaks bahwa imunisasi berbahaya. Yang Anda lakukan ....", opts:[{t:"Menjelaskan manfaat dan keamanan imunisasi dengan bahasa sederhana, menunjukkan data, dan menawarkan diskusi lanjutan tanpa memaksa", s:5},{t:"Meminta tokoh masyarakat/tokoh agama setempat membantu meyakinkan ibu tersebut", s:4},{t:"Mencatat penolakannya dan melaporkannya ke puskesmas", s:3},{t:"Membiarkannya karena itu hak orang tua atas anaknya", s:2},{t:"Memarahi ibu tersebut di depan kader lain agar jera", s:1}], ex:"Edukasi persuasif dan berkelanjutan lebih efektif mengubah perilaku dibanding paksaan atau penghakiman."},
{id:"TKP-728", q:"Anda guru wali kelas. Orang tua murid datang protes keras karena anaknya tidak lolos seleksi PPDB jalur prestasi di sekolah Anda, menuduh panitia tidak adil. Sikap Anda ....", opts:[{t:"Menjelaskan mekanisme dan kriteria seleksi secara transparan, menunjukkan dokumen penilaian, dan menginformasikan jalur sanggah resmi yang tersedia", s:5},{t:"Meminta orang tua menyampaikan keberatan tertulis agar diproses panitia sesuai prosedur", s:4},{t:"Menyarankan orang tua mendaftarkan anaknya ke sekolah lain saja", s:3},{t:"Membela panitia dan menyatakan keputusan sudah final tidak bisa diganggu gugat", s:2},{t:"Mengusir orang tua tersebut karena mengganggu ketertiban sekolah", s:1}], ex:"Transparansi data dan penyediaan kanal sanggah resmi adalah respons profesional atas keberatan masyarakat."},
{id:"TKP-729", q:"Anda petugas PPDB dinas pendidikan. Ditemukan berkas calon siswa yang diduga dipalsukan (KK/surat domisili) agar masuk zonasi favorit. Tindakan Anda ....", opts:[{t:"Memverifikasi keaslian berkas ke dukcapil/kelurahan, dan jika terbukti palsu mendiskualifikasi sesuai aturan sambil mendokumentasikannya", s:5},{t:"Memanggil orang tua untuk klarifikasi dan memberi kesempatan melengkapi berkas yang sah", s:4},{t:"Meloloskan saja karena kasihan pada anaknya", s:3},{t:"Mengabaikan temuan tersebut demi menjaga hubungan baik dengan pihak yang menitipkan", s:2},{t:"Meminta 'uang damai' agar berkasnya tetap diloloskan", s:1}], ex:"Menegakkan verifikasi faktual dan aturan diskualifikasi menjaga keadilan seleksi bagi semua calon siswa."},
{id:"TKP-730", q:"Anda kepala puskesmas. Ada laporan warga bahwa oknum petugas meminta pungutan liar untuk mempercepat surat keterangan sehat. Langkah Anda ....", opts:[{t:"Menindaklanjuti dengan investigasi internal, menindak tegas pelakunya, dan memasang informasi tarif resmi serta kanal pengaduan yang jelas", s:5},{t:"Memanggil petugas yang diduga dan memberinya peringatan tertulis", s:4},{t:"Menunggu laporan resmi tertulis sebelum bertindak", s:3},{t:"Menganggapnya gosip dan tidak menindaklanjuti", s:2},{t:"Menutupi kasusnya agar nama puskesmas tidak tercemar", s:1}], ex:"Respons cepat, investigasi, sanksi tegas, dan perbaikan sistem adalah wujud akuntabilitas pimpinan atas integritas layanan."},
{id:"TKP-731", q:"Anda guru BK. Seorang siswa menjadi korban perundungan dan takut melapor karena pelakunya anak pejabat. Sikap Anda ....", opts:[{t:"Menjamin kerahasiaan dan keamanan pelapor, menindaklanjuti kasusnya sesuai tata tertib tanpa pandang bulu, dan mendampingi korban", s:5},{t:"Memediasi kedua pihak dengan melibatkan orang tua masing-masing secara adil", s:4},{t:"Menasihati korban agar menghindari pelaku dan tidak memancing masalah", s:3},{t:"Membiarkan karena menganggapnya masalah sepele antar-anak", s:2},{t:"Menyalahkan korban yang dianggap terlalu sensitif", s:1}], ex:"Perlindungan korban tanpa pandang status pelaku adalah prinsip keadilan dan profesionalisme guru BK."},
{id:"TKP-732", q:"Anda petugas administrasi sekolah. Orang tua siswa kurang mampu menunggak biaya kegiatan dan malu mengambil rapor anaknya. Tindakan Anda ....", opts:[{t:"Melayani pengambilan rapor tanpa mempersulit, lalu menginformasikan skema keringanan/cicilan dan bantuan yang tersedia", s:5},{t:"Memberikan rapornya sambil mencatat tunggakannya untuk ditagih kemudian", s:4},{t:"Meminta orang tua melunasi dulu sebagian sebelum rapor diserahkan", s:3},{t:"Menahan rapor sampai tunggakan lunas sesuai aturan sekolah", s:2},{t:"Menyindir orang tua tersebut di depan orang tua lain agar segera membayar", s:1}], ex:"Hak siswa atas dokumen pendidikannya tidak boleh disandera oleh tunggakan; solusi pembiayaan yang manusiawi adalah jalan profesional."},
{id:"TKP-733", q:"Anda perawat puskesmas. Pasien dengan gangguan jiwa datang tanpa pendamping dan berperilaku gelisah di ruang tunggu sehingga pasien lain takut. Sikap Anda ....", opts:[{t:"Mendekatinya dengan tenang dan ramah, menenangkan, lalu melayani kebutuhannya secara terpisah dengan tetap menghormati martabatnya", s:5},{t:"Memprioritaskan pelayanannya agar ia cepat selesai dan situasi kondusif", s:4},{t:"Meminta satpam mengeluarkannya dari ruang tunggu", s:3},{t:"Membiarkannya karena bukan wewenang Anda menanganinya", s:2},{t:"Mengusirnya dengan kasar agar pasien lain tidak kabur", s:1}], ex:"Pendekatan humanis yang menenangkan sekaligus melindungi martabat pasien gangguan jiwa mencerminkan pelayanan kesehatan yang inklusif."},
{id:"TKP-734", q:"Anda petugas laboratorium RSUD. Pasien peserta BPJS mengeluh hasil labnya lama keluar sementara pasien umum lebih cepat. Sikap Anda ....", opts:[{t:"Menjelaskan alur dan estimasi waktu pemeriksaan secara terbuka, memastikan tidak ada diskriminasi layanan, dan mempercepat sesuai antrean yang adil", s:5},{t:"Mengecek status pemeriksaannya dan memberi tahu kapan hasilnya keluar", s:4},{t:"Memintanya bersabar karena memang antrean sedang banyak", s:3},{t:"Menjawab bahwa pasien umum memang mendapat prioritas karena membayar lebih", s:2},{t:"Mengabaikan keluhannya dan melanjutkan pekerjaan", s:1}], ex:"Menegaskan kesetaraan layanan tanpa diskriminasi status kepesertaan adalah kewajiban etik petugas kesehatan."},
{id:"TKP-735", q:"Anda guru kelas inklusi. Seorang siswa penyandang disabilitas netra kesulitan mengikuti pelajaran karena belum ada buku braille. Tindakan Anda ....", opts:[{t:"Menyesuaikan metode mengajar (penjelasan lisan rinci, audio), berkoordinasi dengan sekolah untuk pengadaan materi aksesibel, dan memastikan ia tetap terlibat aktif", s:5},{t:"Memintanya duduk di depan dan membacakan materi penting untuknya", s:4},{t:"Menyarankan orang tuanya mencarikan buku braille sendiri", s:3},{t:"Membiarkannya mengikuti seadanya karena keterbatasan fasilitas", s:2},{t:"Menyarankan agar ia pindah ke sekolah luar biasa saja", s:1}], ex:"Adaptasi metode dan advokasi pemenuhan hak atas materi aksesibel adalah wujud pendidikan inklusif yang nyata."},
{id:"TKP-736", q:"Anda petugas gizi puskesmas. Ditemukan balita gizi buruk di wilayah kerja, tetapi orang tuanya jarang datang ke posyandu karena sibuk bekerja. Langkah Anda ....", opts:[{t:"Melakukan kunjungan rumah untuk pemantauan, memberi edukasi gizi praktis sesuai kondisi keluarga, dan merujuk ke program bantuan yang ada", s:5},{t:"Berkonsultasi dengan kader posyandu untuk memantau balita tersebut secara berkala", s:4},{t:"Mengirim surat panggilan agar orang tuanya datang ke puskesmas", s:3},{t:"Mencatat kasusnya dan menunggu orang tua datang sendiri", s:2},{t:"Menyalahkan orang tua yang dianggap tidak peduli pada anaknya", s:1}], ex:"Pelayanan jemput bola melalui kunjungan rumah menjangkau kelompok rentan yang tidak terlayani pendekatan pasif."},
{id:"TKP-737", q:"Anda staf dinas pendidikan. Sekolah swasta kecil mengeluh pencairan dana BOS selalu terlambat sehingga operasional terganggu. Sikap Anda ....", opts:[{t:"Menelusuri hambatan pencairannya, membantu sekolah melengkapi persyaratan, dan mempercepat proses sesuai ketentuan", s:5},{t:"Menjelaskan alur pencairan dan persyaratan yang harus dipenuhi sekolah", s:4},{t:"Meminta sekolah menunggu karena memang antrean pencairan banyak", s:3},{t:"Menyalahkan operator sekolah yang dianggap lambat mengusulkan", s:2},{t:"Mengabaikan keluhan karena sekolah swasta bukan prioritas", s:1}], ex:"Membantu menyelesaikan hambatan administratif mitra layanan adalah bentuk pelayanan publik yang responsif."},
{id:"TKP-738", q:"Anda dokter gigi puskesmas. Pasien anak menangis ketakutan dan menolak diperiksa, sementara orang tuanya memaksa dengan cara membentak. Sikap Anda ....", opts:[{t:"Menenangkan anak dengan pendekatan ramah dan permainan, meminta orang tua bersabar, lalu melakukan pemeriksaan bertahap", s:5},{t:"Menunda pemeriksaan dan menjadwalkan ulang dengan persiapan yang lebih baik", s:4},{t:"Memaksa pemeriksaan cepat-cepat mumpung anak ditahan orang tuanya", s:3},{t:"Menolak memeriksa anak yang tidak kooperatif", s:2},{t:"Ikut membentak anak agar diam dan patuh", s:1}], ex:"Pendekatan ramah-anak membangun kepercayaan dan membuat layanan kesehatan gigi tidak menjadi pengalaman traumatis."},
{id:"TKP-739", q:"Anda petugas pendaftaran RSUD. Sistem antrean online down dan puluhan pasien menumpuk di loket dan harus dilayani manual. Tindakan Anda ....", opts:[{t:"Segera beralih ke sistem manual yang tertib (nomor antrean kertas), menginformasikan estimasi waktu, dan melaporkan gangguan ke tim IT", s:5},{t:"Melayani satu per satu secepat mungkin sambil meminta pasien bersabar", s:4},{t:"Menutup loket sementara sampai sistem kembali normal", s:3},{t:"Menyuruh pasien pulang dan kembali esok hari", s:2},{t:"Membiarkan pasien berebut antrean tanpa pengaturan", s:1}], ex:"Rencana cadangan manual yang tertib plus komunikasi yang jelas menjaga layanan tetap berjalan saat sistem gagal."},
{id:"TKP-740", q:"Anda guru. Seorang siswa cerdas dari keluarga miskin terancam putus sekolah karena harus bekerja membantu orang tua. Sikap Anda ....", opts:[{t:"Berkonsultasi dengan orang tua dan pihak sekolah tentang beasiswa/bantuan (KIP, baznas), serta fleksibilitas agar ia tetap bisa bersekolah", s:5},{t:"Memberi motivasi kepada siswa agar tetap semangat dan tidak menyerah", s:4},{t:"Melaporkan kondisinya ke kepala sekolah untuk dicarikan solusi", s:3},{t:"Menerima keputusannya sebagai realitas ekonomi keluarga", s:2},{t:"Menganggapnya bukan urusan guru karena di luar jam sekolah", s:1}], ex:"Guru yang proaktif menghubungkan siswa dengan skema bantuan yang ada menjalankan peran perlindungan hak anak atas pendidikan."},
{id:"TKP-741", q:"Anda petugas farmasi RSUD. Keluarga pasien meminta penjelasan karena obat yang diresepkan berbeda dari yang biasa diminum pasien. Sikap Anda ....", opts:[{t:"Menjelaskan dengan sabar bahwa itu obat generik yang setara, menunjukkan perbandingannya, dan menawarkan konfirmasi ke dokter bila masih ragu", s:5},{t:"Menjelaskan singkat bahwa obatnya sama khasiatnya hanya beda merek", s:4},{t:"Menyuruh keluarga bertanya langsung ke dokternya", s:3},{t:"Mengabaikan pertanyaan karena resep dokter tidak bisa diganggu gugat", s:2},{t:"Memarahi keluarga yang dianggap tidak percaya pada rumah sakit", s:1}], ex:"Edukasi obat yang sabar dan terbuka membangun kepercayaan pasien terhadap layanan farmasi."},
{id:"TKP-742", q:"Anda petugas kesehatan lingkungan. Warga menolak fogging DBD karena khawatir asapnya berbahaya bagi anak-anak. Sikap Anda ....", opts:[{t:"Menjelaskan keamanan dan manfaat fogging dengan data, menawarkan penjadwalan saat anak tidak di rumah, dan mengedukasi 3M sebagai pencegahan utama", s:5},{t:"Melakukan fogging di rumah-rumah yang bersedia sambil terus mengedukasi yang menolak", s:4},{t:"Memaksa fogging karena demi kepentingan kesehatan bersama", s:3},{t:"Membatalkan fogging di wilayah tersebut", s:2},{t:"Mengancam warga akan didenda jika menolak fogging", s:1}], ex:"Menghormati kekhawatiran warga sambil memberi edukasi dan alternatif jadwal adalah strategi kesehatan masyarakat yang efektif."},
{id:"TKP-743", q:"Anda wali kelas. Dua orang tua murid bertengkar di grup WhatsApp kelas hingga mengganggu dan menyeret nama sekolah. Tindakan Anda ....", opts:[{t:"Menengahi secara bijak, mengingatkan etika berkomunikasi di grup, dan menawarkan mediasi tatap muka untuk akar masalahnya", s:5},{t:"Mengingatkan di grup agar perselisihan pribadi tidak dibawa ke forum kelas", s:4},{t:"Keluar dari grup agar tidak terseret konflik", s:3},{t:"Membiarkan karena itu urusan antar orang tua", s:2},{t:"Memihak salah satu orang tua yang Anda kenal lebih dekat", s:1}], ex:"Guru sebagai penengah yang netral menjaga iklim komunikasi yang sehat antara sekolah dan orang tua."},
{id:"TKP-744", q:"Anda petugas puskesmas keliling. Di daerah terpencil, warga lebih percaya dukun beranak daripada bidan untuk persalinan. Strategi Anda ....", opts:[{t:"Merangkul dukun beranak sebagai mitra (kader), melatihnya mengenali tanda bahaya, dan mengajaknya merujuk persalinan berisiko ke fasilitas kesehatan", s:5},{t:"Mengadakan penyuluhan rutin tentang pentingnya persalinan oleh tenaga kesehatan", s:4},{t:"Melaporkan dukun beranak tersebut agar ditertibkan aparat", s:3},{t:"Membiarkan kebiasaan warga karena sudah turun-temurun", s:2},{t:"Mengejek kepercayaan warga sebagai kuno dan tidak masuk akal", s:1}], ex:"Kemitraan dengan tokoh lokal yang dipercaya masyarakat adalah strategi budaya yang terbukti menurunkan risiko persalinan."},
{id:"TKP-745", q:"Anda petugas rekam medis. Keluarga pasien meminta salinan rekam medis untuk rujukan ke rumah sakit lain, tetapi prosedurnya membutuhkan persetujuan dokter. Sikap Anda ....", opts:[{t:"Membantu mengurus persetujuan dokter secepatnya, menjelaskan alurnya, dan memastikan keluarga mendapat salinannya tanpa berbelit", s:5},{t:"Meminta keluarga menunggu dokter selesai visite untuk meminta persetujuan", s:4},{t:"Menolak karena belum ada persetujuan dokter", s:3},{t:"Menyuruh keluarga mengurus sendiri ke bagian yang tidak jelas", s:2},{t:"Memberi salinan diam-diam tanpa prosedur agar cepat", s:1}], ex:"Memfasilitasi hak pasien atas datanya dengan tetap menempuh prosedur yang benar menyeimbangkan pelayanan dan kepatuhan."},
{id:"TKP-746", q:"Anda guru olahraga. Seorang siswi meminta izin tidak ikut pelajaran renang karena alasan keyakinan/agama terkait pakaian. Sikap Anda ....", opts:[{t:"Menghargai keyakinannya, memberi tugas pengganti yang setara (misal teori/latihan darat), dan memastikan ia tidak didiskriminasi", s:5},{t:"Mengizinkannya tidak ikut renang dengan tugas pengganti yang wajar", s:4},{t:"Memaksanya ikut karena itu kurikulum wajib untuk semua", s:3},{t:"Memberi nilai rendah karena tidak mengikuti praktik", s:2},{t:"Mengejek keyakinannya di depan teman-temannya", s:1}], ex:"Akomodasi yang wajar atas keyakinan peserta didik tanpa mengurangi capaian pembelajaran adalah praktik pendidikan yang inklusif."},
{id:"TKP-747", q:"Anda petugas BPJS di RSUD. Pasien tidak paham perbedaan layanan kelas 1, 2, 3 dan menuntut naik kelas tanpa paham konsekuensinya. Sikap Anda ....", opts:[{t:"Menjelaskan perbedaan hak dan kewajiban tiap kelas dengan bahasa sederhana, termasuk biaya selisihnya, agar keputusannya tepat", s:5},{t:"Memberi brosur penjelasan dan mempersilakan pasien memilih setelah membacanya", s:4},{t:"Menaikkan kelasnya sesuai permintaan tanpa penjelasan", s:3},{t:"Menolak permintaannya karena dianggap merepotkan administrasi", s:2},{t:"Menyuruh pasien mengurus sendiri ke kantor BPJS", s:1}], ex:"Edukasi yang jelas sebelum pasien memutuskan memastikan pilihan yang diambil benar-benar sesuai kebutuhan dan kemampuannya."},
{id:"TKP-748", q:"Anda petugas sanitarian. Kantin sekolah kedapatan tidak higienis dan beberapa siswa keracunan makanan ringan. Langkah Anda ....", opts:[{t:"Menindaklanjuti dengan pemeriksaan, pembinaan higiene pada pengelola kantin, dan koordinasi dengan sekolah untuk pengawasan berkala", s:5},{t:"Memberi peringatan tertulis kepada pengelola kantin agar memperbaiki kebersihan", s:4},{t:"Menutup kantin sementara sampai dinyatakan layak", s:3},{t:"Menganggapnya kasus kecil dan tidak menindaklanjuti", s:2},{t:"Menyalahkan siswa yang jajan sembarangan", s:1}], ex:"Pembinaan plus pengawasan berkelanjutan menyelesaikan akar masalah keamanan pangan, bukan sekadar menghukum."},
{id:"TKP-749", q:"Anda guru. Siswa Anda ketahuan menyontek saat ujian dengan catatan kecil. Sikap Anda ....", opts:[{t:"Menegur secara pribadi, memberi kesempatan memperbaiki diri, mendokumentasikan sesuai tata tertib, dan membina kejujurannya", s:5},{t:"Memberi sanksi sesuai tata tertib sekolah secara proporsional", s:4},{t:"Mengurangi nilainya tanpa penjelasan", s:3},{t:"Membiarkan karena kasihan ia akan tidak lulus", s:2},{t:"Mempermalukannya di depan kelas sebagai efek jera", s:1}], ex:"Penegakan disiplin yang mendidik menyeimbangkan ketegasan aturan dengan pembinaan karakter siswa."},
{id:"TKP-750", q:"Anda petugas puskesmas. Warga difabel kursi roda kesulitan mengakses gedung puskesmas karena tidak ada ramp. Tindakan Anda ....", opts:[{t:"Membantu mobilitasnya saat itu juga dan mengusulkan pengadaan ramp/fasilitas aksesibel ke pimpinan sebagai perbaikan layanan", s:5},{t:"Memindahkan pelayanannya ke ruangan lantai dasar agar ia tetap terlayani", s:4},{t:"Memintanya datang dengan pendamping lain kali", s:3},{t:"Menyuruhnya menunggu di luar sampai gilirannya", s:2},{t:"Mengabaikan karena pembangunan ramp bukan wewenang Anda", s:1}], ex:"Solusi langsung saat itu plus advokasi perbaikan fasilitas menunjukkan keberpihakan pada layanan inklusif."}
,
{id:"TKP-751", q:"Anda bidan desa. Seorang ibu melahirkan di rumah dibantu dukun dan bayinya tidak menangis (asfiksia). Anda dipanggil warga dalam keadaan panik. Tindakan Anda ....", opts:[{t:"Segera melakukan resusitasi bayi sesuai prosedur sambil meminta warga menyiapkan rujukan ke puskesmas/RS", s:5},{t:"Memeriksa kondisi ibu dan bayi lalu memutuskan tindakan gawat darurat yang diperlukan", s:4},{t:"Menyarankan warga membawa ibu dan bayi ke puskesmas secepatnya", s:3},{t:"Menunggu sampai situasi lebih tenang sebelum bertindak", s:2},{t:"Menyalahkan dukun yang menangani persalinan tersebut", s:1}], ex:"Respons gawat darurat yang cepat dan tepat pada bayi asfiksia menentukan keselamatan nyawanya."},
{id:"TKP-752", q:"Anda petugas ambulans desa. Keluarga pasien kritis meminta diantar ke RS swasta yang jauh karena tidak percaya RSUD, padahal kondisi pasien tidak memungkinkan perjalanan jauh. Sikap Anda ....", opts:[{t:"Menjelaskan risiko medis perjalanan jauh dengan jujur, menyarankan RSUD terdekat untuk stabilisasi dulu, dan menghormati keputusan akhir keluarga", s:5},{t:"Mengantar ke RS swasta sesuai permintaan keluarga karena itu hak mereka", s:4},{t:"Menolak mengantar dan menyuruh keluarga mencari ambulans sendiri", s:3},{t:"Mengantar sambil menyalahkan keluarga jika terjadi sesuatu di jalan", s:2},{t:"Membiarkan pasien tanpa memberi penjelasan apa pun", s:1}], ex:"Edukasi risiko yang jujur membantu keluarga mengambil keputusan terbaik bagi keselamatan pasien."},
{id:"TKP-753", q:"Anda petugas kesehatan haji daerah. Calon jemaah lansia dengan komorbid memaksa dinyatakan laik terbang padahal hasil pemeriksaan tidak memenuhi syarat. Sikap Anda ....", opts:[{t:"Menjelaskan hasil pemeriksaan secara objektif, risiko kesehatannya, dan prosedur istitha'ah sesuai ketentuan", s:5},{t:"Menyarankan pemeriksaan ulang di fasilitas yang lebih lengkap untuk kepastian", s:4},{t:"Meloloskannya karena kasihan ia sudah menunggu bertahun-tahun", s:3},{t:"Menolak tanpa penjelasan dan menyuruhnya menerima nasib", s:2},{t:"Meminta imbalan agar hasil pemeriksaannya diloloskan", s:1}], ex:"Integritas hasil pemeriksaan kesehatan melindungi keselamatan jemaah; keputusan medis tidak boleh dikompromikan oleh empati semata."},
{id:"TKP-754", q:"Anda guru PAUD. Seorang anak menunjukkan tanda-tanda kekerasan di rumah (memar, ketakutan). Tindakan Anda ....", opts:[{t:"Mendokumentasikan temuan, berkonsultasi dengan kepala sekolah, dan melaporkan ke mekanisme perlindungan anak yang berlaku", s:5},{t:"Berbicara dengan anak secara lembut untuk memahami situasinya", s:4},{t:"Menasihati orang tua agar tidak kasar pada anak", s:3},{t:"Menganggapnya urusan rumah tangga dan tidak campur tangan", s:2},{t:"Menyebarkan cerita tersebut ke orang tua lain", s:1}], ex:"Guru wajib menjadi garda depan perlindungan anak: dokumentasi dan pelaporan resmi, bukan penghakiman atau gosip."},
{id:"TKP-755", q:"Anda petugas imunisasi. Saat sweeping ke sekolah, beberapa siswa kabur dan bersembunyi karena takut disuntik. Sikap Anda ....", opts:[{t:"Berkolaborasi dengan guru untuk edukasi yang menenangkan, memberi contoh yang tidak menakutkan, dan melayani yang bersedia tanpa paksaan", s:5},{t:"Menunggu sampai siswa tenang lalu melayani satu per satu dengan pendekatan ramah", s:4},{t:"Memaksa siswa yang kabur untuk tetap diimunisasi", s:3},{t:"Melewatkan siswa yang kabur dan tidak menindaklanjuti", s:2},{t:"Menghukum siswa yang kabur agar jera", s:1}], ex:"Pendekatan persuasif yang melibatkan guru lebih efektif mencapai cakupan imunisasi tanpa trauma pada anak."},
{id:"TKP-756", q:"Anda petugas puskesmas. Pasien ODGJ yang sudah stabil meminta surat keterangan sehat untuk melamar pekerjaan, tetapi Anda ragu karena stigma di masyarakat. Sikap Anda ....", opts:[{t:"Menilai kondisi klinisnya secara objektif; jika memang stabil dan layak, terbitkan surat sesuai hasil pemeriksaan tanpa diskriminasi", s:5},{t:"Berkonsultasi dengan dokter penanggung jawab sebelum menerbitkan surat", s:4},{t:"Menolak dengan alasan menjaga nama baik puskesmas", s:3},{t:"Menunda-nunda penerbitan suratnya", s:2},{t:"Memberi surat dengan catatan diagnosis yang mempermalukan pasien", s:1}], ex:"Penilaian objektif tanpa stigma membuka akses ODGJ yang pulih terhadap haknya untuk bekerja."},
{id:"TKP-757", q:"Anda petugas dinas kesehatan. Ada laporan klinik swasta membuang limbah medis sembarangan ke sungai. Langkah Anda ....", opts:[{t:"Melakukan inspeksi lapangan, mengambil bukti, dan menindak sesuai peraturan perundang-undangan yang berlaku", s:5},{t:"Memberi teguran tertulis dan tenggat perbaikan pengelolaan limbahnya", s:4},{t:"Meminta klinik membuat surat pernyataan tidak mengulangi", s:3},{t:"Mengabaikan karena klinik swasta bukan wewenang pembinaan Anda", s:2},{t:"Meminta 'uang tutup mulut' agar laporan tidak diproses", s:1}], ex:"Penegakan aturan limbah medis melindungi kesehatan masyarakat dan lingkungan dari bahaya infeksi."},
{id:"TKP-758", q:"Anda guru. Orang tua siswa berprestasi meminta Anda memberi bocoran soal olimpiade agar anaknya menang. Sikap Anda ....", opts:[{t:"Menolak dengan tegas namun sopan, menjelaskan bahwa kemenangan harus diraih dengan jujur, dan menawarkan bimbingan belajar yang intensif sebagai gantinya", s:5},{t:"Menolak dan melaporkan tawaran tersebut ke kepala sekolah", s:4},{t:"Mengabaikan permintaan tersebut tanpa merespons", s:3},{t:"Memberi sedikit 'kisi-kisi' karena kasihan pada anaknya", s:2},{t:"Menerima imbalan dan memberi bocoran soal", s:1}], ex:"Menolak kecurangan dengan tegas sambil menawarkan pembinaan yang sah menjaga integritas kompetisi dan mendidik sportivitas."},
{id:"TKP-759", q:"Anda petugas Puskesmas Pembantu (Pustu). Warga datang di luar jam layanan dengan keluhan nyeri dada. Sikap Anda ....", opts:[{t:"Segera memeriksa tanda vitalnya, memberi pertolongan awal, dan merujuk ke puskesmas induk/RS jika mengarah ke kegawatan", s:5},{t:"Melayaninya meski di luar jam karena keluhannya berpotensi gawat", s:4},{t:"Menyuruhnya datang kembali saat jam layanan buka", s:3},{t:"Memberi obat pereda nyeri seadanya tanpa pemeriksaan", s:2},{t:"Menolak melayani karena sudah tutup", s:1}], ex:"Keluhan nyeri dada adalah potensi kegawatan; pelayanan kesehatan tidak boleh berhenti pada jam dinding."},
{id:"TKP-760", q:"Anda petugas administrasi RSUD. Pasien tidak mampu membutuhkan surat keterangan tidak mampu untuk keringanan biaya, tetapi ia tidak membawa dokumen pendukung. Sikap Anda ....", opts:[{t:"Membantu mengurus suratnya dengan berkoordinasi ke kelurahan/dinas sosial, menjelaskan syaratnya, dan memproses keringanan sementara yang dimungkinkan", s:5},{t:"Memberi daftar persyaratan dan membantunya menghubungi kelurahan", s:4},{t:"Memintanya melengkapi dokumen dulu sebelum diproses", s:3},{t:"Menolak memproses sampai semua dokumen lengkap", s:2},{t:"Menyuruhnya membayar penuh karena tidak bisa membuktikan ketidakmampuannya", s:1}], ex:"Proaktif memfasilitasi akses jaminan keringanan bagi warga tidak mampu adalah inti pelayanan kesehatan yang berkeadilan."},
{id:"TKP-761", q:"Anda guru ekstrakurikuler. Seorang siswa berbakat tidak bisa ikut lomba karena orang tuanya tidak mampu membayar biaya pendaftaran. Sikap Anda ....", opts:[{t:"Mengupayakan pembiayaan dari dana sekolah/sponsor/beasiswa agar bakatnya tetap tersalurkan", s:5},{t:"Menghubungi panitia lomba untuk meminta keringanan biaya", s:4},{t:"Meminta siswa mencari sponsor sendiri", s:3},{t:"Membiarkannya tidak ikut karena keterbatasan biaya", s:2},{t:"Menggantikannya dengan siswa lain yang mampu membayar", s:1}], ex:"Guru yang memperjuangkan akses bagi siswa berbakat kurang mampu menjalankan pemerataan kesempatan pendidikan."},
{id:"TKP-762", q:"Anda petugas surveilans. Ditemukan kasus suspek campak di sebuah sekolah dan orang tua menolak anaknya diperiksa. Sikap Anda ....", opts:[{t:"Menjelaskan risiko penularan dan pentingnya pemeriksaan, berkoordinasi dengan sekolah, dan melakukan penyelidikan epidemiologi sesuai protokol", s:5},{t:"Meminta bantuan kepala sekolah untuk membujuk orang tua", s:4},{t:"Mencatat penolakannya dan menghentikan penyelidikan", s:3},{t:"Membiarkan karena takut konflik dengan orang tua", s:2},{t:"Mengumumkan nama anak tersebut agar dijauhi teman-temannya", s:1}], ex:"Investigasi wabah yang tegas namun komunikatif melindungi seluruh komunitas sekolah dari penularan."},
{id:"TKP-763", q:"Anda perawat. Pasien meminta Anda merahasiakan penyakit menularnya dari keluarganya yang tinggal serumah. Sikap Anda ....", opts:[{t:"Menghormati kerahasiaan pasien sambil mengedukasinya tentang pentingnya memberitahu keluarga demi pencegahan penularan, dan menawarkan bantuan menyampaikannya", s:5},{t:"Meyakinkan pasien agar bersedia memberitahu keluarganya sendiri", s:4},{t:"Langsung memberitahu keluarganya demi kepentingan pencegahan", s:3},{t:"Membiarkan tanpa edukasi apa pun", s:2},{t:"Menyebarkan informasi penyakitnya ke tetangga agar waspada", s:1}], ex:"Menyeimbangkan kerahasiaan pasien dengan edukasi pencegahan adalah dilema etik yang diselesaikan secara profesional."},
{id:"TKP-764", q:"Anda petugas loket puskesmas. Seorang pasien tunarungu kesulitan berkomunikasi dan antrean mulai protes karena lama. Sikap Anda ....", opts:[{t:"Melayaninya dengan sabar menggunakan tulisan/gambar/isyarat sederhana, dan meminta pengertian antrean lain", s:5},{t:"Meminta bantuan rekan yang bisa bahasa isyarat", s:4},{t:"Memintanya menuliskan keperluannya di kertas", s:3},{t:"Melewatkannya dan melayani pasien berikutnya dulu", s:2},{t:"Menyuruhnya kembali dengan pendamping yang bisa mendengar", s:1}], ex:"Kesabaran dan adaptasi komunikasi memastikan warga difabel mendapat layanan yang setara."},
{id:"TKP-765", q:"Anda guru. Nilai rapor seorang siswa anjlok drastis dan ia tampak murung serta menarik diri. Sikap Anda ....", opts:[{t:"Mengajaknya berbicara secara pribadi dengan empati, menggali masalahnya, dan merujuk ke guru BK bila diperlukan", s:5},{t:"Menghubungi orang tuanya untuk menanyakan kondisi di rumah", s:4},{t:"Menasihatinya agar lebih giat belajar", s:3},{t:"Membiarkan karena menganggapnya fase remaja biasa", s:2},{t:"Memarahinya karena nilainya turun", s:1}], ex:"Kepekaan guru terhadap perubahan perilaku siswa dapat menjadi deteksi dini masalah yang lebih serius."},
{id:"TKP-766", q:"Anda petugas kesehatan. Saat penyuluhan stunting, warga berpendapat anak pendek itu keturunan dan tidak bisa diubah. Sikap Anda ....", opts:[{t:"Menjelaskan dengan bukti sederhana perbedaan genetik vs stunting akibat gizi, menunjukkan contoh perbaikan gizi, dan mengajak memantau tumbuh kembang", s:5},{t:"Menunjukkan data dan grafik pertumbuhan anak sebagai bahan edukasi", s:4},{t:"Memaksa warga menerima program pemberian makanan tambahan", s:3},{t:"Membiarkan pendapat warga karena sulit diubah", s:2},{t:"Mengejek warga yang dianggap tidak paham kesehatan", s:1}], ex:"Edukasi berbasis bukti dengan bahasa yang mudah dipahami perlahan mengubah keyakinan yang menghambat kesehatan anak."},
{id:"TKP-767", q:"Anda petugas pendaftaran sekolah. Calon siswa pindahan dari daerah konflik tidak memiliki rapor lengkap karena sekolah lamanya tutup. Sikap Anda ....", opts:[{t:"Menerimanya dengan asesmen penempatan dan surat keterangan, berkoordinasi dengan dinas untuk pemenuhan dokumennya", s:5},{t:"Menerimanya sementara sambil menunggu dokumen dilengkapi", s:4},{t:"Menolak sampai rapor lengkap diserahkan", s:3},{t:"Menyuruhnya kembali ke daerah asal mengurus dokumen", s:2},{t:"Menolak karena dianggap merepotkan administrasi", s:1}], ex:"Fleksibilitas administratif bagi anak dalam situasi darurat menjamin hak pendidikan tidak terputus."},
{id:"TKP-768", q:"Anda petugas puskesmas. Listrik padam saat pelayanan vaksinasi dan cold chain vaksin terancam. Tindakan Anda ....", opts:[{t:"Segera memindahkan vaksin ke termos/cooler box, menghubungi PLN/teknisi, dan memastikan rantai dingin tetap terjaga", s:5},{t:"Menghentikan vaksinasi sementara dan mengamankan vaksin", s:4},{t:"Melanjutkan vaksinasi seperti biasa tanpa pengamanan khusus", s:3},{t:"Membiarkan vaksin di kulkas yang mati", s:2},{t:"Pulang karena listrik padam dan pelayanan tidak bisa berjalan", s:1}], ex:"Penyelamatan rantai dingin adalah prioritas karena vaksin yang rusak membahayakan pasien dan merugikan negara."},
{id:"TKP-769", q:"Anda guru. Siswa Anda menjadi korban penyebaran foto pribadinya oleh teman sekelas di media sosial. Sikap Anda ....", opts:[{t:"Segera membantu menghapus penyebaran, mendampingi korban, menindak pelaku sesuai tata tertib, dan mengedukasi kelas tentang etika digital", s:5},{t:"Melaporkan kasusnya ke kepala sekolah dan orang tua kedua pihak", s:4},{t:"Menasihati korban agar lebih hati-hati berbagi foto", s:3},{t:"Menganggapnya masalah pribadi di luar sekolah", s:2},{t:"Menyalahkan korban yang dianggap ceroboh", s:1}], ex:"Respons cepat, perlindungan korban, dan edukasi etika digital adalah penanganan profesional kasus kekerasan siber di sekolah."},
{id:"TKP-770", q:"Anda petugas puskesmas. Seorang pasien dengan HIV meminta dirujuk diam-diam karena takut dipecat jika tempat kerjanya tahu. Sikap Anda ....", opts:[{t:"Menjamin kerahasiaan statusnya sesuai etik, memproses rujukan secara diskret, dan mengedukasinya tentang hak-haknya sebagai ODHA", s:5},{t:"Memproses rujukannya tanpa mencantumkan diagnosis pada surat yang tidak perlu", s:4},{t:"Menolak membantu karena takut ikut disalahkan", s:3},{t:"Memberitahu atasannya demi 'kebaikan bersama'", s:2},{t:"Menyebarkan statusnya agar rekan kerjanya waspada", s:1}], ex:"Kerahasiaan status HIV adalah hak pasien yang dilindungi; pelanggaran etik ini berakibat diskriminasi serius."}
,
{id:"TKP-771", q:"Anda dokter puskesmas. Keluarga pasien yang sembuh memberi amplop 'ucapan terima kasih'. Sikap Anda ....", opts:[{t:"Menolak dengan halus sambil menjelaskan bahwa melayani pasien adalah tugas dan tidak perlu imbalan", s:5},{t:"Menolak dan melaporkan ke atasan sesuai aturan gratifikasi", s:4},{t:"Menerima karena nilainya kecil dan sebagai tanda terima kasih", s:3},{t:"Menerima dan membaginya dengan rekan sejawat", s:2},{t:"Meminta tambahan karena merasa jasanya besar", s:1}], ex:"Menolak gratifikasi dalam bentuk apa pun menjaga integritas dan kepercayaan publik pada tenaga kesehatan."},
{id:"TKP-772", q:"Anda panitia PPDB. Seorang pejabat menitipkan keponakannya agar diloloskan meski nilainya di bawah passing grade. Sikap Anda ....", opts:[{t:"Menolak titipan tersebut dengan sopan dan tetap berpegang pada hasil seleksi yang objektif", s:5},{t:"Menjelaskan aturan seleksi dan menyarankan jalur resmi yang masih memungkinkan", s:4},{t:"Melaporkannya ke ketua panitia/kepala sekolah", s:3},{t:"Meloloskan karena takut karier Anda terancam", s:2},{t:"Meloloskan dengan imbalan tertentu", s:1}], ex:"Menolak intervensi kekuasaan dalam seleksi adalah benteng integritas dunia pendidikan."},
{id:"TKP-773", q:"Anda apoteker RSUD. Seorang sales obat menawarkan komisi jika Anda meresepkan/merekomendasikan produknya ke dokter. Sikap Anda ....", opts:[{t:"Menolak tawaran tersebut karena resep harus berdasarkan kebutuhan medis pasien, bukan komisi", s:5},{t:"Menolak dan melaporkan ke komite farmasi dan terapi", s:4},{t:"Menerima brosurnya saja tanpa komitmen", s:3},{t:"Menerima komisi karena menganggapnya hal biasa di industri farmasi", s:2},{t:"Aktif mempromosikan produknya demi komisi besar", s:1}], ex:"Keputusan terapi yang dipengaruhi komisi membahayakan pasien dan melanggar etik profesi kesehatan."},
{id:"TKP-774", q:"Anda guru. Rekan sejawat mengajak Anda mengubah nilai siswa titipan orang kaya agar naik kelas. Sikap Anda ....", opts:[{t:"Menolak ajakan tersebut dan tetap menilai berdasarkan capaian belajar yang sebenarnya", s:5},{t:"Menolak dan mengingatkan rekan tentang risiko pelanggaran etiknya", s:4},{t:"Mengabaikan ajakan tanpa merespons", s:3},{t:"Ikut mengubah karena tidak enak menolak rekan", s:2},{t:"Ikut mengubah dengan imbalan dari orang tua siswa", s:1}], ex:"Integritas penilaian akademik tidak bisa ditawar; nilai harus mencerminkan kemampuan nyata siswa."},
{id:"TKP-775", q:"Anda petugas pengadaan alat kesehatan. Rekanan menawarkan 'fee' agar perusahaannya dimenangkan dalam tender. Sikap Anda ....", opts:[{t:"Menolak dan memastikan proses tender berjalan transparan sesuai aturan pengadaan", s:5},{t:"Menolak dan melaporkan ke aparat pengawas internal", s:4},{t:"Mendengarkan tawarannya tetapi tidak menindaklanjuti", s:3},{t:"Menerima karena merasa gaji PNS kurang", s:2},{t:"Menerima dan memenangkan rekanan tersebut", s:1}], ex:"Pengadaan alkes yang bersih menjamin kualitas alat untuk pasien dan menghindari kerugian negara."},
{id:"TKP-776", q:"Anda bidan. Keluarga pasien meminta Anda memalsukan surat keterangan lahir (tanggal/tempat) untuk keperluan administrasi. Sikap Anda ....", opts:[{t:"Menolak dengan tegas karena dokumen kelahiran harus sesuai fakta dan pemalsuan adalah tindak pidana", s:5},{t:"Menolak dan menjelaskan risiko hukum bagi semua pihak", s:4},{t:"Menunda dengan alasan formulir habis", s:3},{t:"Membantu karena kasihan pada keluarganya", s:2},{t:"Membantu dengan imbalan uang", s:1}], ex:"Dokumen kependudukan yang dipalsukan merusak tertib administrasi negara dan berisiko pidana."},
{id:"TKP-777", q:"Anda kepala sekolah. Seorang donatur menawarkan bantuan pembangunan dengan syarat anaknya diterima tanpa seleksi. Sikap Anda ....", opts:[{t:"Menolak syarat tersebut; bantuan diterima hanya tanpa ikatan yang melanggar aturan penerimaan siswa", s:5},{t:"Menerima bantuan tetapi tetap menjalankan seleksi secara adil", s:4},{t:"Mempertimbangkan karena sekolah sangat membutuhkan dana", s:3},{t:"Menerima dan meloloskan anak donatur", s:2},{t:"Meminta tambahan dana sebagai 'uang pangkal khusus'", s:1}], ex:"Menjaga independensi sekolah dari transaksi donasi-seleksi melindungi keadilan bagi semua calon siswa."},
{id:"TKP-778", q:"Anda perawat. Dokter meminta Anda memberikan obat di luar dosis yang tertulis di resep karena 'sudah biasa begitu'. Sikap Anda ....", opts:[{t:"Mengonfirmasi ulang ke dokter dan menolak memberikan dosis yang tidak sesuai resep tertulis demi keselamatan pasien", s:5},{t:"Meminta dokter memperbaiki resep tertulisnya terlebih dahulu", s:4},{t:"Mengikuti perintah dokter karena ia yang bertanggung jawab", s:3},{t:"Memberikan dosis tersebut tanpa bertanya", s:2},{t:"Memberikan dosis lebih besar agar pasien cepat sembuh", s:1}], ex:"Prinsip 'lima benar' pemberian obat mewajibkan perawat memverifikasi, bukan sekadar menuruti perintah lisan."},
{id:"TKP-779", q:"Anda petugas laboratorium. Atasan meminta Anda memanipulasi hasil lab pasien VIP agar terlihat baik. Sikap Anda ....", opts:[{t:"Menolak permintaan tersebut, mencatatnya sebagai bukti, dan melaporkannya melalui jalur pengawasan resmi", s:5},{t:"Menolak karena hasil laboratorium harus apa adanya; manipulasi membahayakan diagnosis dan terapi pasien", s:4},{t:"Meminta atasan membuat perintah tertulis", s:3},{t:"Memanipulasi karena perintah atasan", s:2},{t:"Memanipulasi dan meminta imbalan", s:1}], ex:"Hasil lab yang dimanipulasi dapat menyebabkan kesalahan diagnosis fatal; menolak, mendokumentasikan, dan melaporkan permintaan tersebut adalah wujud integritas tenaga kesehatan."},
{id:"TKP-780", q:"Anda guru. Menjelang ujian sekolah, kunci jawaban beredar di grup siswa dan Anda diminta rekan untuk 'tutup mata'. Sikap Anda ....", opts:[{t:"Menolak, melaporkan kebocoran ke panitia, dan mengusulkan pengamanan/penggantian soal", s:5},{t:"Menolak ikut serta dan menegur siswa yang menyebarkan", s:4},{t:"Diam saja agar tidak bermasalah dengan rekan", s:3},{t:"Ikut tutup mata karena kasihan pada siswa", s:2},{t:"Ikut menyebarkan kunci jawaban", s:1}], ex:"Menjaga kerahasiaan soal adalah amanah profesi; kebocoran yang dibiarkan merusak makna evaluasi."},
{id:"TKP-781", q:"Anda petugas puskesmas. Teman dekat Anda meminta didahulukan tanpa mengikuti antrean resmi. Sikap Anda ....", opts:[{t:"Menolak dengan halus dan memintanya mengikuti antrean seperti pasien lain", s:5},{t:"Menjelaskan sistem antrean dan memintanya bersabar menunggu giliran", s:4},{t:"Mendahulukannya diam-diam agar tidak ketahuan", s:3},{t:"Mendahulukannya karena ia teman dekat", s:2},{t:"Mendahulukannya dan meminta imbalan", s:1}], ex:"Profesionalisme menuntut perlakuan setara; mendahulukan kerabat adalah bentuk nepotisme layanan."},
{id:"TKP-782", q:"Anda petugas dinas pendidikan. Ditemukan indikasi mark-up dana BOS oleh oknum kepala sekolah. Sikap Anda ....", opts:[{t:"Melaporkan temuan ke inspektorat/aparat pengawas dengan bukti yang ada sesuai prosedur", s:5},{t:"Melakukan verifikasi lapangan terlebih dahulu sebelum melaporkan", s:4},{t:"Menasihati kepala sekolah agar tidak mengulangi", s:3},{t:"Mendiamkan karena tidak ingin bermusuhan", s:2},{t:"Meminta bagian dari dana tersebut sebagai tutup mulut", s:1}], ex:"Dana BOS adalah hak siswa; penyimpangannya wajib dilaporkan melalui jalur pengawasan resmi."},
{id:"TKP-783", q:"Anda dokter. Pasien meminta surat keterangan sakit palsu untuk bolos kerja. Sikap Anda ....", opts:[{t:"Menolak karena surat keterangan dokter harus berdasarkan pemeriksaan medis yang sebenarnya", s:5},{t:"Menolak dan menjelaskan konsekuensi hukum surat palsu", s:4},{t:"Memberi surat untuk sakit ringan yang sebenarnya tidak ada", s:3},{t:"Memberi surat karena kasihan ia butuh istirahat", s:2},{t:"Memberi surat dengan imbalan", s:1}], ex:"Surat keterangan medis palsu merusak kredibilitas profesi dan dapat menjerat dokter secara hukum."},
{id:"TKP-784", q:"Anda perawat. Rekan sejawat sering datang terlambat dan meminta Anda menutupi absensinya. Sikap Anda ....", opts:[{t:"Menolak menutupi dan mengingatkannya tentang tanggung jawab serta dampaknya pada pasien", s:5},{t:"Menolak dan menyarankan ia izin resmi jika berhalangan", s:4},{t:"Menutupi sekali ini saja karena kasihan", s:3},{t:"Rutin menutupi demi menjaga hubungan baik", s:2},{t:"Ikut-ikutan terlambat karena rekan Anda melakukannya", s:1}], ex:"Menutupi pelanggaran disiplin rekan adalah pelanggaran integritas yang merugikan pasien dan tim."},
{id:"TKP-785", q:"Anda petugas farmasi. Stok obat mahal menipis dan ada godaan menjualnya ke luar dengan harga tinggi. Sikap Anda ....", opts:[{t:"Tetap menyalurkan sesuai resep dan prosedur; melaporkan kebutuhan pengadaan tambahan", s:5},{t:"Mengamankan stok dan melapor ke atasan tentang potensi penyalahgunaan", s:4},{t:"Menyimpan sebagian untuk 'jaga-jaga' pribadi", s:3},{t:"Menjual sebagian kecil karena desakan ekonomi", s:2},{t:"Menjual stok tersebut untuk keuntungan pribadi", s:1}], ex:"Obat negara adalah amanah untuk pasien; penggelapannya adalah korupsi yang membahayakan nyawa."},
{id:"TKP-786", q:"Anda guru. Orang tua murid menawarkan hadiah mahal menjelang pembagian rapor. Sikap Anda ....", opts:[{t:"Menolak hadiah tersebut dengan sopan dan menjelaskan penilaian dilakukan objektif", s:5},{t:"Menerima hanya sebagai tanda terima kasih setelah rapor dibagikan dan nilainya objektif", s:4},{t:"Menerima karena menganggapnya budaya wajar", s:3},{t:"Menerima dan menaikkan nilai anaknya", s:2},{t:"Meminta hadiah yang lebih besar", s:1}], ex:"Gratifikasi menjelang penilaian rawan memengaruhi objektivitas; penolakan adalah sikap paling aman dan profesional."},
{id:"TKP-787", q:"Anda petugas kesehatan. Perusahaan rokok menawarkan sponsor kegiatan penyuluhan kesehatan remaja. Sikap Anda ....", opts:[{t:"Menolak sponsor tersebut karena bertentangan dengan misi kesehatan dan etika promosi kesehatan", s:5},{t:"Menolak dan mencari sponsor lain yang sejalan dengan misi kesehatan", s:4},{t:"Menerima dengan syarat tanpa logo perusahaan", s:3},{t:"Menerima karena dana kegiatan memang kurang", s:2},{t:"Menerima dan mempromosikan produknya", s:1}], ex:"Menerima sponsor industri rokok untuk kegiatan kesehatan remaja adalah konflik kepentingan yang merusak kredibilitas."},
{id:"TKP-788", q:"Anda bidan praktik. Pasien meminta tindakan aborsi dengan imbalan besar. Sikap Anda ....", opts:[{t:"Menolak dengan tegas karena melanggar hukum, etik, dan sumpah profesi", s:5},{t:"Menolak dan merujuknya ke konseling resmi yang sah", s:4},{t:"Menolak tetapi tidak melaporkan", s:3},{t:"Mempertimbangkan karena imbalan besar", s:2},{t:"Menerima dan melakukan tindakan tersebut", s:1}], ex:"Aborsi ilegal adalah tindak pidana dan pelanggaran berat etik kebidanan; penolakan tegas adalah satu-satunya sikap benar."},
{id:"TKP-789", q:"Anda petugas IT sekolah. Kepala sekolah meminta Anda mengubah data Dapodik agar sekolah mendapat bantuan lebih besar. Sikap Anda ....", opts:[{t:"Menolak karena data Dapodik harus faktual; manipulasi adalah pelanggaran hukum", s:5},{t:"Menolak dan menjelaskan risiko sanksi bagi sekolah", s:4},{t:"Menunda dengan berbagai alasan", s:3},{t:"Mengubah sebagian data yang 'tidak terlalu terlihat'", s:2},{t:"Mengubah data sesuai permintaan", s:1}], ex:"Data pendidikan nasional yang dimanipulasi merusak perencanaan kebijakan dan berujung sanksi."},
{id:"TKP-790", q:"Anda dokter. Keluarga pasien kritis menawarkan 'uang terima kasih' besar agar pasiennya diprioritaskan di ICU yang penuh. Sikap Anda ....", opts:[{t:"Menolak dan menjelaskan alokasi ICU berdasarkan tingkat kegawatan medis, bukan kemampuan membayar", s:5},{t:"Menolak serta memastikan penilaian triase berjalan objektif", s:4},{t:"Menerima karena ICU memang bisa diatur", s:3},{t:"Memprioritaskan pasien tersebut karena imbalannya besar", s:2},{t:"Meminta bayaran lebih tinggi dari keluarga pasien lain yang antre", s:1}], ex:"Alokasi sumber daya kritis harus berdasarkan kebutuhan medis; suap dalam triase mengorbankan nyawa pasien lain."}
,
{id:"TKP-791", q:"Anda perawat. Anda menyaksikan rekan memberi obat yang salah kepada pasien tetapi ia meminta Anda diam. Sikap Anda ....", opts:[{t:"Melaporkan kejadian ke atasan/komite keselamatan pasien agar pasien mendapat penanganan dan sistem diperbaiki", s:5},{t:"Mendesak rekan untuk mengakui kesalahannya dan memperbaiki segera", s:4},{t:"Diam karena tidak ingin mengkhianati rekan", s:3},{t:"Diam dan berharap tidak terjadi apa-apa pada pasien", s:2},{t:"Ikut menutupi dan memalsukan catatan pemberian obat", s:1}], ex:"Keselamatan pasien di atas solidaritas semu; pelaporan insiden adalah kewajiban etik dan sistemik."},
{id:"TKP-792", q:"Anda guru. Anda mengetahui rekan guru melakukan kekerasan fisik pada siswa tetapi korban takut melapor. Sikap Anda ....", opts:[{t:"Melaporkan ke kepala sekolah/pengawas sesuai mekanisme perlindungan anak yang berlaku", s:5},{t:"Membujuk korban dan orang tuanya untuk berani melapor", s:4},{t:"Menasihati rekan tersebut secara pribadi", s:3},{t:"Diam karena bukan urusan Anda", s:2},{t:"Menyebarkan kabar tersebut sebagai gosip", s:1}], ex:"Kekerasan terhadap anak oleh pendidik wajib dilaporkan; mendiamkan sama dengan membiarkan berulang."},
{id:"TKP-793", q:"Anda petugas puskesmas. Dana program kesehatan ibu-anak diduga dipakai atasan untuk kepentingan pribadi. Sikap Anda ....", opts:[{t:"Melaporkan dugaan tersebut ke inspektorat/WBS dengan bukti yang dimiliki", s:5},{t:"Mengumpulkan bukti lebih kuat sebelum melapor resmi", s:4},{t:"Menasihati atasan agar mengembalikan dana", s:3},{t:"Diam karena takut dimutasi", s:2},{t:"Ikut menikmati dana tersebut", s:1}], ex:"Whistleblowing melalui kanal resmi adalah wujud integritas ASN dalam menjaga uang negara."},
{id:"TKP-794", q:"Anda apoteker. Resep dokter terbaca meragukan (dosis tidak wajar) tetapi pasien sudah menunggu lama. Sikap Anda ....", opts:[{t:"Mengonfirmasi ke dokter penulis resep sebelum menyerahkan obat, meski pasien harus menunggu", s:5},{t:"Menyerahkan obat sambil menyarankan pasien bertanya ulang ke dokter", s:4},{t:"Menyerahkan obat sesuai tulisan apa adanya", s:3},{t:"Menyerahkan obat dengan dosis dikira-kira sendiri", s:2},{t:"Menyerahkan obat tanpa memeriksa sama sekali", s:1}], ex:"Verifikasi resep yang meragukan adalah benteng terakhir keselamatan pasien; kecepatan tidak boleh mengorbankan ketepatan."},
{id:"TKP-795", q:"Anda guru. Sekolah Anda ditunjuk sebagai tempat ujian nasional dan ada tekanan agar nilai siswa bagus 'demi nama sekolah'. Sikap Anda ....", opts:[{t:"Tetap menjalankan ujian secara jujur sesuai prosedur tanpa rekayasa nilai", s:5},{t:"Menolak tekanan dan melaporkan ke pengawas ujian", s:4},{t:"Ikut arahan pimpinan karena perintah atasan", s:3},{t:"Membantu siswa dengan 'bocoran halus' saat ujian", s:2},{t:"Mengubah nilai hasil ujian agar terlihat bagus", s:1}], ex:"Integritas evaluasi nasional menentukan kepercayaan publik pada ijazah; rekayasa nilai adalah kebohongan institusional."},
{id:"TKP-796", q:"Anda petugas kesehatan. Saat dinas luar, Anda melihat warung makan yang sangat tidak higienis tetapi pemiliknya kerabat Anda. Sikap Anda ....", opts:[{t:"Tetap melakukan pembinaan/pemeriksaan sesuai prosedur tanpa pandang hubungan kekerabatan", s:5},{t:"Memberi teguran dan tenggat perbaikan seperti kepada pelaku usaha lain", s:4},{t:"Menasihati secara kekeluargaan tanpa tindakan resmi", s:3},{t:"Melewatkan warung tersebut dari pemeriksaan", s:2},{t:"Melindungi warung tersebut dari razia", s:1}], ex:"Profesionalisme menuntut perlakuan sama; kekerabatan tidak boleh menjadi tameng pelanggaran higiene."},
{id:"TKP-797", q:"Anda dokter. Pasien meminta Anda merahasiakan hasil tes narkoba positifnya dari perusahaan tempat ia bekerja. Sikap Anda ....", opts:[{t:"Menjelaskan batasan kerahasiaan sesuai aturan (misal tes untuk kepentingan perusahaan), dan memproses sesuai prosedur yang sah", s:5},{t:"Menyarankan pasien berkonsultasi ke bagian hukum/SDM perusahaannya", s:4},{t:"Menyembunyikan hasilnya karena kasihan", s:3},{t:"Memalsukan hasil tes menjadi negatif", s:2},{t:"Memeras pasien dengan ancaman menyebarkan hasilnya", s:1}], ex:"Hasil pemeriksaan resmi memiliki prosedur hukum; dokter tidak boleh memalsukan maupun disuap untuk itu."},
{id:"TKP-798", q:"Anda petugas administrasi sekolah. Orang tua meminta Anda 'mempercepat' legalisasi ijazah dengan imbalan. Sikap Anda ....", opts:[{t:"Menolak imbalan dan memproses legalisasi sesuai antrean/prosedur yang berlaku", s:5},{t:"Menolak serta menjelaskan bahwa layanan legalisasi gratis dan berprosedur", s:4},{t:"Menerima imbalan tetapi tetap memproses normal", s:3},{t:"Menerima imbalan dan mendahulukan prosesnya", s:2},{t:"Meminta imbalan lebih besar", s:1}], ex:"Pungli dalam layanan administrasi pendidikan merusak kepercayaan; penolakan tegas adalah standar."},
{id:"TKP-799", q:"Anda perawat. Pasien VIP meminta seluruh tim medis merahasiakan penyakitnya bahkan dari keluarga intinya, padahal keluarganya perlu tahu untuk perawatan di rumah. Sikap Anda ....", opts:[{t:"Menghormati permintaan pasien sambil mengedukasinya tentang pentingnya keluarga mengetahui untuk keberlangsungan perawatan", s:5},{t:"Menyarankan pasien menunjuk satu anggota keluarga yang dipercaya", s:4},{t:"Langsung memberi tahu keluarganya tanpa izin pasien", s:3},{t:"Mengabaikan permintaan dan membiarkan keluarga menebak-nebak", s:2},{t:"Menyebarkan informasi penyakitnya ke media", s:1}], ex:"Edukasi persuasif menghormati otonomi pasien sekaligus menjembatani kebutuhan perawatan yang aman."},
{id:"TKP-800", q:"Anda guru. Anda diminta menjadi tim sukses salah satu calon dalam pemilihan ketua OSIS. Sikap Anda ....", opts:[{t:"Menolak dan menjaga netralitas dengan memfasilitasi pemilihan yang adil bagi semua calon", s:5},{t:"Menolak secara halus dengan alasan fokus pada tugas mengajar", s:4},{t:"Menerima tetapi berusaha tetap adil", s:3},{t:"Menerima karena calon tersebut murid kesayangan Anda", s:2},{t:"Menerima dan mengarahkan siswa memilih calon tersebut", s:1}], ex:"Netralitas guru dalam demokrasi sekolah mendidik siswa tentang keadilan prosedural."},
{id:"TKP-801", q:"Anda petugas puskesmas. Sisa vaksin program hampir kedaluwarsa dan ada tawaran 'mengamankan' untuk dijual ke klinik swasta. Sikap Anda ....", opts:[{t:"Menolak dan melaporkan penggunaan sisa vaksin sesuai prosedur (pemusnahan/pelaporan resmi)", s:5},{t:"Melaporkan tawaran tersebut ke atasan dan inspektorat", s:4},{t:"Mengabaikan tawaran tersebut", s:3},{t:"Menjual sebagian kecil untuk tambahan penghasilan", s:2},{t:"Menjual seluruh sisa vaksin tersebut", s:1}], ex:"Vaksin program adalah barang milik negara; penggelapannya membahayakan pasien dan melanggar hukum."},
{id:"TKP-802", q:"Anda kepala puskesmas. Ada konflik antara dokter senior dan perawat muda yang mengganggu pelayanan. Sikap Anda ....", opts:[{t:"Memediasi keduanya secara adil, menggali akar masalah, dan menetapkan pembagian tugas yang jelas", s:5},{t:"Memanggil keduanya untuk klarifikasi dan pembinaan", s:4},{t:"Memihak dokter senior karena lebih berpengalaman", s:3},{t:"Membiarkan karena menganggapnya masalah pribadi", s:2},{t:"Memutasi perawat muda sebagai 'kambing hitam'", s:1}], ex:"Mediasi yang adil dan solusi struktural menyelesaikan konflik tanpa mengorbankan keadilan."},
{id:"TKP-803", q:"Anda guru. Nilai tugas siswa Anda bocor ke orang tua sebelum dibagikan resmi karena keteledoran Anda. Sikap Anda ....", opts:[{t:"Mengakui keteledoran, meminta maaf, dan memperbaiki pengamanan data nilai ke depan", s:5},{t:"Mengakui dan menjelaskan kronologinya kepada pihak yang terdampak", s:4},{t:"Menyalahkan sistem yang tidak aman", s:3},{t:"Menyangkal dan menuduh pihak lain membocorkan", s:2},{t:"Membiarkan tanpa klarifikasi", s:1}], ex:"Mengakui kesalahan dan memperbaikinya adalah wujud akuntabilitas profesional guru."},
{id:"TKP-804", q:"Anda petugas kesehatan haji. Jemaah meminta Anda meloloskan vaksinasi meningitis palsu (tanpa disuntik). Sikap Anda ....", opts:[{t:"Menolak karena sertifikat vaksinasi harus berdasarkan tindakan nyata; pemalsuan membahayakan jemaah dan melanggar hukum", s:5},{t:"Menolak dan menjelaskan risiko kesehatannya jika tidak divaksinasi", s:4},{t:"Memberi sertifikat tanpa menyuntik karena kasihan", s:3},{t:"Memberi sertifikat dengan imbalan", s:2},{t:"Menyuntikkan cairan lain agar terlihat seperti vaksinasi", s:1}], ex:"Sertifikat vaksinasi palsu membahayakan jemaah di tanah suci dan merusak kepercayaan antarnegara."},
{id:"TKP-805", q:"Anda perawat. Keluarga pasien protes karena Anda dianggap 'jutek' saat pelayanan. Sikap Anda ....", opts:[{t:"Menerima masukan dengan lapang, meminta maaf, dan memperbaiki cara berkomunikasi ke depan", s:5},{t:"Menjelaskan kondisi saat itu tanpa defensif dan meminta maaf", s:4},{t:"Membela diri bahwa Anda memang sedang sibuk", s:3},{t:"Mengabaikan protes tersebut", s:2},{t:"Balik memarahi keluarga yang protes", s:1}], ex:"Menerima kritik dengan lapang dan memperbaiki diri adalah ciri profesional yang berorientasi pelayanan."},
{id:"TKP-806", q:"Anda guru. Siswa Anda tertangkap membawa rokok elektrik (vape) di sekolah. Sikap Anda ....", opts:[{t:"Menindak sesuai tata tertib, memanggil orang tua, dan membina pemahaman bahayanya", s:5},{t:"Menyita barangnya dan memberi sanksi pembinaan", s:4},{t:"Menasihati saja tanpa sanksi resmi", s:3},{t:"Membiarkan karena menganggapnya tren remaja biasa", s:2},{t:"Ikut menggunakan bersama siswa", s:1}], ex:"Penegakan tata tertib yang disertai pembinaan melindungi siswa dari bahaya adiksi."},
{id:"TKP-807", q:"Anda petugas puskesmas. Ada pasien yang selalu datang dengan keluhan yang berubah-ubah dan diduga hanya mencari surat sakit. Sikap Anda ....", opts:[{t:"Tetap memeriksa secara profesional dan objektif; menerbitkan surat sakit hanya bila ada indikasi medis", s:5},{t:"Menegur halus dan mengingatkannya agar tidak menyalahgunakan layanan", s:4},{t:"Memberi surat sakit agar ia tidak bolak-balik", s:3},{t:"Mengusirnya karena dianggap mengganggu", s:2},{t:"Memberi surat sakit dengan imbalan", s:1}], ex:"Pemeriksaan objektif melindungi integritas surat medis tanpa menuduh pasien secara sepihak."},
{id:"TKP-808", q:"Anda dokter. Rumah sakit tempat Anda bekerja kekurangan alat, dan Anda tergoda merujuk semua pasien ke klinik pribadi Anda. Sikap Anda ....", opts:[{t:"Tidak menyalahgunakan wewenang rujukan; merujuk berdasarkan kebutuhan medis ke fasilitas yang tepat", s:5},{t:"Melaporkan kekurangan alat ke manajemen untuk pengadaan", s:4},{t:"Merujuk sesekali ke klinik pribadi saat memang dibutuhkan", s:3},{t:"Rutin mengarahkan pasien ke klinik pribadi demi keuntungan", s:2},{t:"Memaksa pasien berobat ke klinik pribadi Anda", s:1}], ex:"Konflik kepentingan dalam rujukan merugikan pasien dan institusi; keputusan medis harus bebas kepentingan pribadi."},
{id:"TKP-809", q:"Anda petugas TU sekolah. Dana kegiatan siswa dikelola tanpa pembukuan jelas oleh panitia. Sikap Anda ....", opts:[{t:"Mendorong dan membantu panitia membuat pembukuan yang transparan dan dapat dipertanggungjawabkan", s:5},{t:"Melaporkan kondisi tersebut ke kepala sekolah untuk pembinaan", s:4},{t:"Membiarkan karena bukan wewenang langsung Anda", s:3},{t:"Ikut menggunakan dana tersebut untuk keperluan pribadi", s:2},{t:"Memanfaatkan ketidakjelasan untuk mengambil dana", s:1}], ex:"Transparansi pengelolaan dana kegiatan mendidik siswa tentang akuntabilitas sejak dini."},
{id:"TKP-810", q:"Anda bidan. Ibu nifas mengalami perdarahan dan suaminya menolak rujukan karena alasan biaya. Sikap Anda ....", opts:[{t:"Bertindak cepat menstabilkan, menjelaskan bahwa ini kegawatan yang mengancam nyawa, dan mengupayakan rujukan dengan skema pembiayaan yang ada", s:5},{t:"Memberi pertolongan awal maksimal sambil terus membujuk keluarga", s:4},{t:"Menerima penolakan dan hanya memantau dari rumah", s:3},{t:"Pergi karena keluarga tidak kooperatif", s:2},{t:"Menyalahkan suami jika terjadi sesuatu", s:1}], ex:"Perdarahan nifas adalah kegawatan obstetri; kegigihan menyelamatkan nyawa didahulukan dari hambatan administratif."}
,
{id:"TKP-811", q:"Anda dokter muda di puskesmas. Dokter senior sering mengabaikan usulan Anda dalam rapat penanganan kasus. Sikap Anda ....", opts:[{t:"Tetap menyampaikan usulan berbasis bukti dengan sopan dan mencari forum diskusi kasus yang konstruktif", s:5},{t:"Mendiskusikan langsung dengan dokter senior secara pribadi dan terbuka", s:4},{t:"Diam dan mengikuti saja keputusan senior", s:3},{t:"Mengeluhkan perlakuan tersebut ke rekan sejawat", s:2},{t:"Menolak bekerja sama dengan dokter senior tersebut", s:1}], ex:"Kolaborasi profesional menuntut keberanian menyampaikan pendapat berbasis bukti dengan tetap menghormati senioritas."},
{id:"TKP-812", q:"Anda perawat. Bidan dan dokter berbeda pendapat tentang penanganan pasien persalinan di depan keluarga pasien. Sikap Anda ....", opts:[{t:"Mengusulkan diskusi tim secara tertutup untuk menyatukan keputusan, lalu menyampaikannya ke keluarga secara kompak", s:5},{t:"Mengikuti keputusan dokter sebagai penanggung jawab medis", s:4},{t:"Mendukung bidan karena ia yang paling paham persalinan", s:3},{t:"Diam dan membiarkan perdebatan berlanjut di depan keluarga", s:2},{t:"Ikut berdebat memihak salah satu pihak", s:1}], ex:"Perbedaan pendapat klinis diselesaikan di forum tim, bukan di depan pasien; kekompakan menjaga kepercayaan."},
{id:"TKP-813", q:"Anda guru. Tim guru sejawat akan mengadakan lesson study tetapi Anda sibuk dengan administrasi. Sikap Anda ....", opts:[{t:"Tetap berpartisipasi aktif karena pengembangan profesional adalah tanggung jawab bersama", s:5},{t:"Mengikuti sebagian sesi yang paling relevan dengan kelas Anda", s:4},{t:"Meminta digantikan rekan lain", s:3},{t:"Tidak ikut dengan alasan sibuk", s:2},{t:"Menganggap lesson study buang-buang waktu", s:1}], ex:"Komitmen pada pengembangan profesional kolektif meningkatkan kualitas pembelajaran seluruh sekolah."},
{id:"TKP-814", q:"Anda petugas puskesmas. Program penanggulangan TB membutuhkan kerja sama lintas program (promkes, lab, farmasi) tetapi masing-masing sibuk. Sikap Anda ....", opts:[{t:"Menginisiasi rapat koordinasi, membagi peran jelas, dan memantau progres bersama", s:5},{t:"Berkonsultasi dengan kepala puskesmas untuk penugasan formal", s:4},{t:"Menjalankan bagian Anda sendiri semampunya", s:3},{t:"Menunggu instruksi atasan tanpa inisiatif", s:2},{t:"Menyalahkan program lain yang tidak kooperatif", s:1}], ex:"Inisiatif mengoordinasikan lintas program adalah kunci keberhasilan program kesehatan masyarakat."},
{id:"TKP-815", q:"Anda petugas ambulans. Sopir dan perawat pendamping berselisih soal rute tercepat ke RS rujukan saat membawa pasien kritis. Sikap Anda ....", opts:[{t:"Segera menyepakati rute berdasarkan informasi lalu lintas terkini dan fokus pada keselamatan pasien", s:5},{t:"Mengikuti rute yang biasa digunakan dan tercepat menurut pengalaman", s:4},{t:"Membiarkan keduanya berdebat sampai sepakat sendiri", s:3},{t:"Memihak salah satu tanpa dasar jelas", s:2},{t:"Berhenti di pinggir jalan sampai perdebatan selesai", s:1}], ex:"Dalam kegawatan, keputusan cepat berbasis data dan fokus pada pasien mengalahkan ego pribadi."},
{id:"TKP-816", q:"Anda guru baru. Rekan senior enggan berbagi perangkat pembelajaran yang ia buat. Sikap Anda ....", opts:[{t:"Membuat perangkat sendiri sambil tetap menjalin hubungan baik dan sesekali berdiskusi untuk saling belajar", s:5},{t:"Meminta dengan sopan dan menjelaskan akan sangat membantu kelas Anda", s:4},{t:"Melaporkan ke kepala sekolah", s:3},{t:"Mengambil diam-diam dari komputernya", s:2},{t:"Memusuhinya dan menyebarkan keburukannya", s:1}], ex:"Kemandirian yang dibarengi hubungan baik membuka peluang kolaborasi tanpa konflik."},
{id:"TKP-817", q:"Anda petugas gizi. Program pemberian makanan tambahan (PMT) untuk balita stunting membutuhkan kader posyandu, tetapi kader merasa terbebani. Sikap Anda ....", opts:[{t:"Berdiskusi dengan kader tentang beban kerjanya, menyederhanakan alur, dan memberi apresiasi serta pendampingan", s:5},{t:"Meminta dukungan kepala desa untuk memotivasi kader", s:4},{t:"Memaksa kader menjalankan sesuai target", s:3},{t:"Mengerjakan sendiri tanpa melibatkan kader", s:2},{t:"Membatalkan program karena kader tidak kooperatif", s:1}], ex:"Memahami beban mitra dan menyederhanakan proses membangun kemitraan yang berkelanjutan."},
{id:"TKP-818", q:"Anda dokter puskesmas. RSUD sering menolak rujukan balik dengan alasan kapasitas, padahal pasien perlu kontrol lanjutan. Sikap Anda ....", opts:[{t:"Membangun komunikasi formal dengan RSUD (jejaring rujukan), mendokumentasikan kasus, dan mengadvokasi ke dinas kesehatan", s:5},{t:"Berkonsultasi via telemedicine/telekonsultasi dengan dokter RSUD untuk penanganan lanjutan", s:4},{t:"Menerima penolakan dan merawat pasien seadanya", s:3},{t:"Menyuruh pasien mencari RS lain sendiri", s:2},{t:"Menyalahkan RSUD di depan pasien", s:1}], ex:"Advokasi sistemik melalui jejaring formal menyelesaikan masalah rujukan balik secara berkelanjutan."},
{id:"TKP-819", q:"Anda guru BK dan wali kelas berbeda pendapat tentang penanganan siswa bermasalah. Sikap Anda ....", opts:[{t:"Menyatukan informasi dan menyusun rencana penanganan bersama yang disepakati kedua pihak", s:5},{t:"Mengikuti saran guru BK sebagai yang lebih ahli", s:4},{t:"Bersikeras dengan pendekatan Anda sendiri", s:3},{t:"Membiarkan siswa tanpa penanganan jelas", s:2},{t:"Saling menyalahkan di depan siswa", s:1}], ex:"Rencana penanganan terpadu antara wali kelas dan guru BK memberi hasil terbaik bagi siswa."},
{id:"TKP-820", q:"Anda petugas surveilans. Saat KLB demam berdarah, dinas kesehatan, puskesmas, dan kecamatan saling menunggu siapa yang bergerak dulu. Sikap Anda ....", opts:[{t:"Mengambil inisiatif mengoordinasikan respons cepat: penyelidikan, fogging, dan edukasi serentak", s:5},{t:"Melaporkan situasi ke pimpinan untuk komando yang jelas", s:4},{t:"Menjalankan tugas surveilans Anda saja", s:3},{t:"Menunggu perintah resmi sebelum bergerak", s:2},{t:"Menyalahkan instansi lain yang lamban", s:1}], ex:"Dalam KLB, inisiatif koordinasi respons cepat menyelamatkan nyawa; birokrasi menunggu adalah kegagalan."},
{id:"TKP-821", q:"Anda perawat senior. Perawat junior melakukan kesalahan prosedur dan takut mengaku. Sikap Anda ....", opts:[{t:"Menciptakan suasana aman untuk mengakui kesalahan, membimbingnya, dan menjadikannya pembelajaran tim", s:5},{t:"Membantunya memperbaiki kesalahan dan melaporkannya sesuai prosedur", s:4},{t:"Memarahinya agar tidak mengulangi", s:3},{t:"Membiarkannya menanggung sendiri", s:2},{t:"Melaporkannya dengan tuduhan berat agar dipecat", s:1}], ex:"Budaya keselamatan yang tidak menghukum mendorong pelaporan insiden dan mencegah terulang."},
{id:"TKP-822", q:"Anda guru. Sekolah mengadakan proyek lintas mata pelajaran tetapi guru-guru sulit menyamakan jadwal. Sikap Anda ....", opts:[{t:"Mengusulkan mekanisme kolaborasi yang fleksibel (dokumen bersama, pertemuan singkat terjadwal) dan aktif menjalankannya", s:5},{t:"Menyesuaikan jadwal Anda dengan mayoritas guru", s:4},{t:"Menjalankan proyek versi mata pelajaran Anda sendiri", s:3},{t:"Menarik diri dari proyek tersebut", s:2},{t:"Menyalahkan koordinator proyek", s:1}], ex:"Solusi kolaborasi yang fleksibel dan inisiatif menjalankannya menunjukkan semangat kerja sama."},
{id:"TKP-823", q:"Anda petugas farmasi dan dokter. Stok obat program terbatas sehingga perlu prioritas pasien. Sikap Anda ....", opts:[{t:"Berdiskusi dengan dokter menentukan kriteria prioritas klinis yang adil dan transparan", s:5},{t:"Mengikuti prioritas yang ditetapkan dokter penanggung jawab", s:4},{t:"Membagi rata tanpa mempertimbangkan kegawatan", s:3},{t:"Mendahulukan pasien yang Anda kenal", s:2},{t:"Menyimpan stok untuk 'orang penting'", s:1}], ex:"Kriteria prioritas klinis yang disepakati tim menjamin keadilan dalam keterbatasan sumber daya."},
{id:"TKP-824", q:"Anda petugas puskesmas. Bidan desa dan kader posyandu berselisih soal jadwal kegiatan sehingga program terganggu. Sikap Anda ....", opts:[{t:"Memfasilitasi musyawarah untuk menyepakati jadwal bersama yang mengakomodasi keduanya", s:5},{t:"Mengusulkan jadwal alternatif yang adil", s:4},{t:"Memihak bidan karena ia petugas resmi", s:3},{t:"Membiarkan perselisihan berlarut", s:2},{t:"Melaporkan keduanya sebagai tidak kooperatif", s:1}], ex:"Fasilitasi musyawarah yang adil memulihkan kerja sama garda depan layanan kesehatan desa."},
{id:"TKP-825", q:"Anda guru. Komite sekolah mengusulkan program yang menurut Anda kurang tepat sasaran. Sikap Anda ....", opts:[{t:"Menyampaikan pandangan Anda dengan data dan alternatif solusi dalam forum komite secara konstruktif", s:5},{t:"Mendiskusikan dengan kepala sekolah sebelum forum komite", s:4},{t:"Diam dan mengikuti keputusan komite", s:3},{t:"Menolak mentah-mentah usulan komite", s:2},{t:"Memprovokasi guru lain menolak usulan tersebut", s:1}], ex:"Menyampaikan kritik berbasis data dengan alternatif solusi adalah partisipasi konstruktif dalam tata kelola sekolah."}
,
{id:"TKP-826", q:"Anda petugas kesehatan. Tim tanggap bencana (BPBD, TNI/Polri, relawan) perlu posko kesehatan terpadu saat banjir. Sikap Anda ....", opts:[{t:"Aktif berkoordinasi membangun posko terpadu dengan pembagian peran jelas antar unsur", s:5},{t:"Menyiapkan layanan kesehatan sesuai tugas dan berkoordinasi dengan komandan posko", s:4},{t:"Menunggu instruksi sebelum menyiapkan apa pun", s:3},{t:"Bekerja sendiri-sendiri tanpa koordinasi", s:2},{t:"Menolak terlibat karena bukan tugas pokok", s:1}], ex:"Koordinasi multipihak yang proaktif adalah kunci respons bencana yang efektif."},
{id:"TKP-827", q:"Anda dokter gigi. Perawat gigi Anda sering tidak menyiapkan alat sesuai kebutuhan tindakan. Sikap Anda ....", opts:[{t:"Membuat standar persiapan alat bersama, melatihnya, dan mengevaluasi secara berkala", s:5},{t:"Berdiskusi langsung tentang kendalanya dan mencari solusi", s:4},{t:"Menyiapkan sendiri alat yang dibutuhkan", s:3},{t:"Memarahinya setiap kali alat kurang", s:2},{t:"Meminta ia dipindahkan", s:1}], ex:"Standar kerja yang disepakati plus pembinaan membangun tim yang solid, bukan sekadar menyalahkan."},
{id:"TKP-828", q:"Anda guru. Wali murid ingin dilibatkan lebih jauh dalam kegiatan sekolah tetapi sebagian guru keberatan. Sikap Anda ....", opts:[{t:"Mengusulkan pola kemitraan yang jelas (batas peran, jadwal) sehingga keterlibatan orang tua terarah dan tidak mengganggu", s:5},{t:"Mendukung keterlibatan dengan rambu-rambu yang disepakati", s:4},{t:"Netral dan mengikuti keputusan mayoritas", s:3},{t:"Menolak keterlibatan orang tua", s:2},{t:"Menghasut guru lain menolak", s:1}], ex:"Kemitraan sekolah-orang tua yang terstruktur menguatkan pendidikan tanpa mengaburkan peran profesional guru."},
{id:"TKP-829", q:"Anda petugas lab. Hasil pemeriksaan pasien kritis perlu segera sampai ke dokter, tetapi sistem informasi sedang lambat. Sikap Anda ....", opts:[{t:"Menghubungi dokter langsung via telepon/radio sambil tetap menginput ke sistem", s:5},{t:"Mengantar hasil cetak langsung ke ruangan dokter", s:4},{t:"Menunggu sistem normal kembali", s:3},{t:"Membiarkan sampai dokter menanyakan", s:2},{t:"Mengabaikan karena bukan tugas mengantar", s:1}], ex:"Komunikasi langsung sebagai cadangan saat sistem gagal menunjukkan orientasi pada keselamatan pasien."},
{id:"TKP-830", q:"Anda bidan koordinator. Bidan-bidan desa jarang melaporkan data persalinan tepat waktu. Sikap Anda ....", opts:[{t:"Menyederhanakan format laporan, memberi umpan balik rutin, dan mengapresiasi yang tepat waktu", s:5},{t:"Mengadakan pertemuan untuk memahami kendala pelaporan mereka", s:4},{t:"Memberi sanksi bagi yang terlambat", s:3},{t:"Membiarkan keterlambatan terjadi terus", s:2},{t:"Memalsukan data agar terlihat lengkap", s:1}], ex:"Memudahkan proses dan memberi apresiasi lebih efektif meningkatkan kepatuhan pelaporan daripada hukuman."},
{id:"TKP-831", q:"Anda guru. Sekolah Anda ditunjuk menjadi sekolah penggerak dan butuh tim inti yang solid. Sikap Anda ....", opts:[{t:"Bergabung aktif, berbagi praktik baik, dan mendukung rekan yang kesulitan beradaptasi", s:5},{t:"Mengikuti program dengan komitmen penuh", s:4},{t:"Ikut sekadarnya karena beban kerja bertambah", s:3},{t:"Menolak terlibat dengan alasan sibuk", s:2},{t:"Menyebarkan pesimisme bahwa program akan gagal", s:1}], ex:"Komitmen kolektif dan saling mendukung menentukan keberhasilan transformasi sekolah."},
{id:"TKP-832", q:"Anda petugas puskesmas. Program Indonesia Sehat dengan Pendekatan Keluarga (PIS-PK) butuh kunjungan rumah terpadu lintas program. Sikap Anda ....", opts:[{t:"Mengorganisasi tim kunjungan terpadu dengan pembagian tugas dan instrumen yang disepakati", s:5},{t:"Berpartisipasi aktif dalam tim kunjungan sesuai peran Anda", s:4},{t:"Melakukan kunjungan sendiri untuk program Anda saja", s:3},{t:"Menolak karena menambah beban kerja", s:2},{t:"Memalsukan data kunjungan", s:1}], ex:"Kunjungan terpadu lintas program efisien dan memberi gambaran kesehatan keluarga yang utuh."},
{id:"TKP-833", q:"Anda perawat ICU. Dokter jaga sulit dihubungi saat kondisi pasien memburuk. Sikap Anda ....", opts:[{t:"Mengikuti protokol eskalasi (hubungi dokter kedua/atasan), melakukan tindakan awal sesuai kewenangan, dan mendokumentasikannya", s:5},{t:"Terus mencoba menghubungi sambil melakukan stabilisasi awal", s:4},{t:"Menunggu sampai dokter bisa dihubungi", s:3},{t:"Bertindak di luar kewenangan tanpa konsultasi", s:2},{t:"Meninggalkan pasien karena dokter tidak ada", s:1}], ex:"Protokol eskalasi yang dijalankan disiplin melindungi pasien saat penanggung jawab sulit dihubungi."},
{id:"TKP-834", q:"Anda guru. Rekan Anda akan mengikuti lomba inovasi pembelajaran dan meminta masukan. Sikap Anda ....", opts:[{t:"Memberi masukan jujur dan membangun, bahkan membantu menyempurnakan inovasinya", s:5},{t:"Memberi masukan seperlunya dengan sopan", s:4},{t:"Memuji seadanya tanpa masukan berarti", s:3},{t:"Menolak dengan alasan sibuk", s:2},{t:"Menjatuhkan dengan kritik pedas karena iri", s:1}], ex:"Mendukung dan mengasah inovasi rekan mencerminkan budaya kolaboratif yang sehat."},
{id:"TKP-835", q:"Anda petugas kesehatan lingkungan. Program sanitasi total berbasis masyarakat (STBM) butuh peran aktif warga yang apatis. Sikap Anda ....", opts:[{t:"Menggerakkan tokoh masyarakat dan kader, memfasilitasi pemicuan, dan mendampingi sampai terbentuk norma baru", s:5},{t:"Melakukan pemicuan dan penyuluhan secara bertahap", s:4},{t:"Membangunkan jamban bantuan tanpa pelibatan warga", s:3},{t:"Membiarkan karena warga tidak peduli", s:2},{t:"Memaksa warga dengan ancaman sanksi", s:1}], ex:"Pemberdayaan masyarakat melalui tokoh lokal menciptakan perubahan perilaku yang berkelanjutan."},
{id:"TKP-836", q:"Anda dokter. Tim medis Anda akan menangani operasi besar pertama di RSUD. Sikap Anda ....", opts:[{t:"Memastikan briefing tim (checklist keselamatan operasi WHO), pembagian peran, dan kesiapan alat dilakukan bersama", s:5},{t:"Mengikuti briefing dan menjalankan peran Anda dengan disiplin", s:4},{t:"Mengandalkan pengalaman masing-masing tanpa briefing", s:3},{t:"Bekerja sendiri-sendiri sesuai kebiasaan", s:2},{t:"Menolak terlibat karena takut gagal", s:1}], ex:"Checklist dan briefing tim terbukti menekan kesalahan operasi; keselamatan pasien adalah kerja tim."},
{id:"TKP-837", q:"Anda guru. Musyawarah guru mata pelajaran (MGMP) di daerah Anda tidak aktif. Sikap Anda ....", opts:[{t:"Menginisiasi pengaktifan kembali dengan agenda yang bermanfaat dan mengajak rekan sejawat", s:5},{t:"Aktif mengikuti jika ada yang menginisiasi", s:4},{t:"Tidak peduli karena sibuk mengajar", s:3},{t:"Menganggap MGMP tidak berguna", s:2},{t:"Menghalangi rekan yang ingin mengaktifkan", s:1}], ex:"Inisiatif menghidupkan forum profesi menunjukkan kepemimpinan dan kepedulian pada mutu."},
{id:"TKP-838", q:"Anda petugas puskesmas. Kader kesehatan dan perangkat desa berbeda pendapat soal lokasi posyandu baru. Sikap Anda ....", opts:[{t:"Memfasilitasi musyawarah dengan kriteria objektif (akses warga, keterjangkauan) hingga tercapai kesepakatan", s:5},{t:"Mengusulkan lokasi netral berdasarkan data cakupan", s:4},{t:"Memihak perangkat desa sebagai pemegang otoritas", s:3},{t:"Membiarkan perdebatan tanpa penyelesaian", s:2},{t:"Memutuskan sepihak tanpa musyawarah", s:1}], ex:"Fasilitasi berbasis data dan musyawarah menghasilkan keputusan yang diterima semua pihak."},
{id:"TKP-839", q:"Anda perawat. Shift Anda selesai tetapi perawat pengganti terlambat dan pasien membutuhkan observasi ketat. Sikap Anda ....", opts:[{t:"Tetap bertugas sampai serah terima dilakukan dengan aman, lalu melaporkan keterlambatan sesuai prosedur", s:5},{t:"Menunggu sambil memberi tahu atasan tentang keterlambatan", s:4},{t:"Pulang tepat waktu dan meninggalkan catatan", s:3},{t:"Pulang tanpa serah terima", s:2},{t:"Pulang dan mematikan alat pantau agar tidak berisik", s:1}], ex:"Serah terima yang aman tidak boleh dikorbankan oleh pergantian shift; keselamatan pasien utama."},
{id:"TKP-840", q:"Anda guru. Sekolah kedatangan guru tamu dari luar daerah untuk berbagi praktik baik. Sikap Anda ....", opts:[{t:"Menyambut terbuka, aktif berdiskusi, dan mengadaptasi praktik baiknya ke kelas Anda", s:5},{t:"Mengikuti sesi berbagi dengan antusias", s:4},{t:"Hadir sekadarnya karena sibuk", s:3},{t:"Tidak hadir dengan berbagai alasan", s:2},{t:"Mencemooh praktik dari daerah lain", s:1}], ex:"Keterbukaan pada praktik baik dari luar memperkaya profesionalisme dan mencegah stagnasi."}
,
{id:"TKP-841", q:"Anda bidan. Keluarga pasien bersikeras memakai jampi-jampi dukun di ruang bersalin dan menolak anjuran medis. Sikap Anda ....", opts:[{t:"Menghormati keyakinannya sambil menjelaskan risiko medis dengan sabar dan mencari jalan tengah yang aman", s:5},{t:"Mengizinkan ritual yang tidak membahayakan sambil tetap melakukan pemantauan medis", s:4},{t:"Melarang keras segala bentuk ritual di fasilitas kesehatan", s:3},{t:"Membiarkan tanpa pemantauan medis", s:2},{t:"Mengejek keyakinan keluarga tersebut", s:1}], ex:"Menghormati budaya sambil menjaga standar medis adalah kompetensi sosial-budaya tenaga kesehatan."},
{id:"TKP-842", q:"Anda guru di daerah transmigran. Siswa dari suku berbeda sering diejek karena logatnya. Sikap Anda ....", opts:[{t:"Menjadikan keberagaman sebagai bahan pembelajaran, menegakkan aturan anti-ejekan, dan membina empati antarsiswa", s:5},{t:"Menegur pelaku ejekan dan mendampingi korban", s:4},{t:"Menasihati korban agar tidak terlalu sensitif", s:3},{t:"Menganggapnya candaan biasa antar-anak", s:2},{t:"Ikut menertawakan logat siswa tersebut", s:1}], ex:"Sekolah wajib menjadi ruang aman bagi semua identitas budaya; pembinaan empati mencegah diskriminasi."},
{id:"TKP-843", q:"Anda perawat. Pasien perempuan meminta hanya dirawat perawat perempuan karena keyakinan agamanya. Sikap Anda ....", opts:[{t:"Mengupayakan pemenuhan permintaan tersebut sejauh memungkinkan dan menghormati keyakinannya", s:5},{t:"Menjelaskan keterbatasan staf sambil berusaha mengakomodasi", s:4},{t:"Menolak karena semua perawat sama profesionalnya", s:3},{t:"Mengabaikan permintaannya", s:2},{t:"Mengejek keyakinannya sebagai berlebihan", s:1}], ex:"Akomodasi yang wajar atas keyakinan pasien meningkatkan kenyamanan dan kepatuhan perawatan."},
{id:"TKP-844", q:"Anda petugas puskesmas di daerah pedalaman. Warga tidak paham bahasa Indonesia dan hanya berbahasa daerah. Sikap Anda ....", opts:[{t:"Belajar bahasa daerah setempat dan melibatkan kader/tokoh lokal sebagai penerjemah dalam pelayanan", s:5},{t:"Menggunakan bahasa isyarat, gambar, dan alat bantu visual", s:4},{t:"Berbicara bahasa Indonesia dengan suara keras", s:3},{t:"Menyuruh warga membawa penerjemah sendiri", s:2},{t:"Menolak melayani karena kendala bahasa", s:1}], ex:"Adaptasi bahasa adalah bagian dari pelayanan; hambatan komunikasi tidak boleh menjadi hambatan akses kesehatan."},
{id:"TKP-845", q:"Anda guru. Siswa berbeda agama ribut soal jadwal kegiatan yang bentrok dengan ibadah. Sikap Anda ....", opts:[{t:"Memfasilitasi dialog, menyesuaikan jadwal secara adil, dan menjadikannya pembelajaran toleransi", s:5},{t:"Mengatur ulang jadwal agar tidak bentrok dengan waktu ibadah", s:4},{t:"Memihak kelompok mayoritas", s:3},{t:"Membiarkan keributan reda sendiri", s:2},{t:"Melarang pembahasan agama di sekolah", s:1}], ex:"Fasilitasi yang adil atas kebutuhan ibadah semua agama menumbuhkan toleransi sejak dini."},
{id:"TKP-846", q:"Anda petugas kesehatan. Masyarakat adat menolak pembangunan poskesdes di tanah ulayat. Sikap Anda ....", opts:[{t:"Berdialog dengan pemuka adat, memahami keberatannya, dan mencari solusi lokasi yang disepakati bersama", s:5},{t:"Melibatkan tokoh adat dalam perencanaan sejak awal", s:4},{t:"Memaksa pembangunan demi kepentingan umum", s:3},{t:"Membatalkan program kesehatan di wilayah tersebut", s:2},{t:"Mengabaikan hak ulayat masyarakat adat", s:1}], ex:"Dialog yang menghormati hak ulayat menghasilkan solusi yang diterima masyarakat adat."},
{id:"TKP-847", q:"Anda perawat. Keluarga pasien ingin membawa pulang ari-ari bayi untuk dikubur sesuai adat. Sikap Anda ....", opts:[{t:"Menghormati adat tersebut dan membantu pengemasan ari-ari secara higienis sesuai prosedur", s:5},{t:"Mengizinkan dengan penjelasan cara penanganan yang aman", s:4},{t:"Melarang karena alasan medis", s:3},{t:"Membuang ari-ari tanpa sepengetahuan keluarga", s:2},{t:"Mengejek adat tersebut sebagai takhayul", s:1}], ex:"Menghormati adat kelahiran dengan tetap menjaga higiene adalah pelayanan yang berbudaya."},
{id:"TKP-848", q:"Anda guru. Orang tua siswa meminta anaknya tidak satu kelompok dengan siswa berkebutuhan khusus. Sikap Anda ....", opts:[{t:"Menolak permintaan tersebut dengan penjelasan tentang nilai inklusi dan manfaat belajar bersama", s:5},{t:"Menjelaskan kebijakan sekolah inklusi kepada orang tua", s:4},{t:"Mengabulkan agar tidak ribut", s:3},{t:"Mengabulkan dan memisahkan siswa tersebut", s:2},{t:"Menyalahkan siswa berkebutuhan khusus sebagai masalah", s:1}], ex:"Menegakkan prinsip inklusi melawan diskriminasi adalah tanggung jawab pendidik."},
{id:"TKP-849", q:"Anda petugas puskesmas. Pasangan beda agama meminta konseling pranikah dan khawatir dihakimi. Sikap Anda ....", opts:[{t:"Melayani konseling secara profesional dan netral tanpa menghakimi pilihan mereka", s:5},{t:"Memberi layanan konseling kesehatan seperti pasangan lainnya", s:4},{t:"Menolak dengan alasan tidak sesuai norma", s:3},{t:"Melayani sambil menceramahi mereka", s:2},{t:"Menyebarkan informasi tentang mereka", s:1}], ex:"Netralitas dan profesionalisme dalam layanan konseling menghormati keberagaman pilihan warga."},
{id:"TKP-850", q:"Anda dokter. Pasien lansia ingin didampingi dukun selama perawatan di RS. Sikap Anda ....", opts:[{t:"Mengizinkan pendampingan yang tidak mengganggu medis sambil menjelaskan batasan keselamatan pasien", s:5},{t:"Mengizinkan dengan pengaturan waktu kunjungan", s:4},{t:"Melarang keras karena tidak ilmiah", s:3},{t:"Mengusir dukun tersebut", s:2},{t:"Mengejek pasien dan keluarganya", s:1}], ex:"Mengakomodasi pendampingan tradisional dalam batasan medis menghormati pasien lansia secara utuh."},
{id:"TKP-851", q:"Anda guru. Siswa pendatang dari daerah konflik diejek sebagai 'pengungsi'. Sikap Anda ....", opts:[{t:"Menegakkan disiplin anti-perundungan, mengedukasi kelas tentang empati, dan mendampingi siswa tersebut beradaptasi", s:5},{t:"Menegur pelaku dan melindungi korban", s:4},{t:"Menasihati korban agar bersabar", s:3},{t:"Menganggapnya fase adaptasi biasa", s:2},{t:"Ikut menyebutnya pengungsi", s:1}], ex:"Perlindungan aktif terhadap siswa rentan dan edukasi empati menciptakan sekolah yang aman."},
{id:"TKP-852", q:"Anda petugas kesehatan jiwa. Warga menganggap pasien gangguan jiwa sebagai 'kesurupan' dan membawanya ke dukun. Sikap Anda ....", opts:[{t:"Mengedukasi keluarga tentang gangguan jiwa sebagai kondisi medis yang bisa diobati, tanpa merendahkan keyakinannya", s:5},{t:"Menawarkan pengobatan medis berdampingan dengan pendekatan yang dihormati keluarga", s:4},{t:"Melarang keras membawa ke dukun", s:3},{t:"Membiarkan karena itu pilihan keluarga", s:2},{t:"Mengejek keyakinan warga", s:1}], ex:"Edukasi yang tidak merendahkan keyakinan membuka jalan bagi pengobatan medis yang diterima."},
{id:"TKP-853", q:"Anda perawat. Pasien waria membutuhkan perawatan dan khawatir didiskriminasi staf. Sikap Anda ....", opts:[{t:"Melayani dengan profesional dan setara, memastikan ia diperlakukan bermartabat oleh seluruh tim", s:5},{t:"Melayani seperti pasien lainnya tanpa perlakuan khusus", s:4},{t:"Memintanya berpenampilan 'normal' selama dirawat", s:3},{t:"Menolak merawatnya", s:2},{t:"Mengolok-oloknya bersama rekan", s:1}], ex:"Pelayanan kesehatan tanpa diskriminasi identitas adalah kewajiban etik universal."},
{id:"TKP-854", q:"Anda guru. Perayaan hari besar agama di sekolah didominasi satu agama dan siswa minoritas merasa tersisih. Sikap Anda ....", opts:[{t:"Mengusulkan perayaan yang inklusif dan memberi ruang bagi semua agama secara proporsional", s:5},{t:"Memastikan siswa minoritas tetap dilibatkan dan dihargai", s:4},{t:"Membiarkan karena mengikuti mayoritas", s:3},{t:"Menganggap siswa minoritas terlalu sensitif", s:2},{t:"Melarang semua perayaan agama di sekolah", s:1}], ex:"Inklusivitas dalam kegiatan keagamaan sekolah menumbuhkan rasa memiliki semua siswa."},
{id:"TKP-855", q:"Anda petugas puskesmas. Nelayan yang melaut berbulan-bulan sulit mengikuti jadwal kontrol penyakit kronisnya. Sikap Anda ....", opts:[{t:"Menyesuaikan jadwal kontrol dengan pola melautnya dan memberi bekal obat serta edukasi yang cukup", s:5},{t:"Memberi obat untuk durasi melaut dengan pemantauan via kader", s:4},{t:"Memaksanya mengikuti jadwal standar puskesmas", s:3},{t:"Menghentikan pengobatannya karena tidak patuh", s:2},{t:"Menyalahkannya sebagai pasien bandel", s:1}], ex:"Menyesuaikan layanan dengan pola hidup pasien meningkatkan kepatuhan pengobatan."}
,
{id:"TKP-856", q:"Anda bidan. Ibu hamil remaja (di bawah umur) datang tanpa pendamping dan ketakutan. Sikap Anda ....", opts:[{t:"Melayani dengan empati tanpa menghakimi, menjaga kerahasiaan, dan merujuk ke layanan konseling serta perlindungan yang tepat", s:5},{t:"Memeriksanya dan menyarankan ia bercerita ke orang tua/wali", s:4},{t:"Menolak melayani tanpa pendamping orang tua", s:3},{t:"Menceramahinya tentang moral", s:2},{t:"Menyebarkan kabar tentangnya", s:1}], ex:"Pelayanan tanpa penghakiman plus rujukan perlindungan adalah respons profesional pada kehamilan remaja."},
{id:"TKP-857", q:"Anda guru. Siswa Anda menikah dini dan ingin tetap bersekolah tetapi malu. Sikap Anda ....", opts:[{t:"Mendukung haknya atas pendidikan, melindunginya dari perundungan, dan berkoordinasi dengan sekolah untuk kelancaran belajarnya", s:5},{t:"Meyakinkannya untuk tetap bersekolah dan menawarkan bantuan", s:4},{t:"Menyarankan ia berhenti sekolah dan fokus berumah tangga", s:3},{t:"Membiarkannya putus sekolah", s:2},{t:"Mengeluarkannya karena mencoreng nama sekolah", s:1}], ex:"Hak atas pendidikan tidak gugur karena status pernikahan; sekolah wajib melindungi."},
{id:"TKP-858", q:"Anda petugas kesehatan. Warga lansia hidup sebatang kara dan sering lupa minum obat. Sikap Anda ....", opts:[{t:"Mengaktifkan kader/posyandu lansia untuk pemantauan rutin dan mengupayakan dukungan sosial baginya", s:5},{t:"Berkunjung berkala untuk memastikan kepatuhan minum obat", s:4},{t:"Mengingatkannya setiap kali bertemu", s:3},{t:"Membiarkan karena tidak ada keluarga yang bertanggung jawab", s:2},{t:"Menganggapnya bukan tanggung jawab puskesmas", s:1}], ex:"Menggerakkan jejaring sosial untuk lansia sebatang kara adalah wujud pelayanan kesehatan yang manusiawi."},
{id:"TKP-859", q:"Anda perawat. Pasien dengan tato dan tindik merasa dipandang sinis oleh staf. Sikap Anda ....", opts:[{t:"Melayani dengan profesional tanpa prasangka dan mengingatkan rekan untuk bersikap sama", s:5},{t:"Melayani seperti pasien lainnya", s:4},{t:"Menasihatinya agar berpenampilan lebih 'pantas'", s:3},{t:"Ikut memandangnya sinis", s:2},{t:"Menolak merawatnya", s:1}], ex:"Penampilan bukan dasar penilaian mutu layanan; profesionalisme menuntut kesetaraan."},
{id:"TKP-860", q:"Anda guru. Siswa Anda berasal dari keluarga narapidana dan dijauhi teman-temannya. Sikap Anda ....", opts:[{t:"Melindungi dari stigma, mengedukasi kelas bahwa anak tidak menanggung dosa orang tua, dan membinanya", s:5},{t:"Mendampingi dan memberi perhatian lebih", s:4},{t:"Membiarkan karena sulit mengubah pandangan teman-temannya", s:3},{t:"Menjauhinya juga agar tidak dicap", s:2},{t:"Menyebarkan latar belakang keluarganya", s:1}], ex:"Anak tidak boleh menanggung stigma orang tua; guru wajib menjadi pelindungnya."},
{id:"TKP-861", q:"Anda petugas puskesmas. Pekerja seks komersial ingin memeriksakan kesehatannya tetapi takut dihakimi. Sikap Anda ....", opts:[{t:"Melayani dengan profesional, menjaga kerahasiaan, dan menawarkan layanan kesehatan reproduksi serta konseling", s:5},{t:"Memeriksanya seperti pasien lainnya tanpa prasangka", s:4},{t:"Melayani sambil menceramahinya", s:3},{t:"Menolak melayani karena pekerjaannya", s:2},{t:"Melaporkan identitasnya ke aparat", s:1}], ex:"Layanan kesehatan tanpa penghakiman bagi kelompok rentan justru menekan penularan penyakit."},
{id:"TKP-862", q:"Anda dokter. Pasien menolak transfusi darah karena keyakinan agama meski kondisinya kritis. Sikap Anda ....", opts:[{t:"Menghormati keputusannya setelah penjelasan risiko yang lengkap, mendokumentasikan informed refusal, dan memberikan alternatif terapi yang diizinkan", s:5},{t:"Menawarkan alternatif terapi non-darah yang tersedia", s:4},{t:"Memaksa transfusi demi menyelamatkan nyawa", s:3},{t:"Membiarkan tanpa penjelasan risiko", s:2},{t:"Mengejek keyakinannya", s:1}], ex:"Otonomi pasien yang terinformasi dihormati; dokumentasi dan alternatif terapi adalah jalan profesional."},
{id:"TKP-863", q:"Anda guru. Siswa difabel intelektual sering menjadi bahan tertawaan di kelas. Sikap Anda ....", opts:[{t:"Menegakkan aturan, mengedukasi empati, dan merancang pembelajaran yang melibatkannya sesuai kemampuannya", s:5},{t:"Melindungi dan menegur pelaku ejekan", s:4},{t:"Memindahkannya ke kelas khusus", s:3},{t:"Membiarkan karena sulit dikendalikan", s:2},{t:"Ikut menertawakannya", s:1}], ex:"Pendidikan inklusi menuntut perlindungan aktif dan desain pembelajaran yang adaptif."},
{id:"TKP-864", q:"Anda petugas kesehatan. Komunitas adat memiliki pantangan tidak boleh difoto saat pengobatan. Sikap Anda ....", opts:[{t:"Menghormati pantangan tersebut dan menyesuaikan dokumentasi (catatan tertulis) tanpa memaksa", s:5},{t:"Meminta izin dan menjelaskan tujuan dokumentasi; menghormati jika ditolak", s:4},{t:"Tetap memotret diam-diam untuk kelengkapan data", s:3},{t:"Memaksa karena itu prosedur", s:2},{t:"Membatalkan pelayanan karena tidak bisa didokumentasikan", s:1}], ex:"Menghormati pantangan adat dalam dokumentasi membangun kepercayaan jangka panjang."},
{id:"TKP-865", q:"Anda perawat. Pasien lansia dengan demensia sering marah dan memukul saat dirawat. Sikap Anda ....", opts:[{t:"Tetap sabar, memahami perilakunya sebagai gejala penyakit, dan menerapkan pendekatan perawatan demensia yang tepat", s:5},{t:"Meminta bantuan keluarga/rekan dalam merawatnya", s:4},{t:"Mengikatnya agar tidak memukul", s:3},{t:"Membentak balik agar ia takut", s:2},{t:"Menolak merawatnya", s:1}], ex:"Memahami demensia sebagai kondisi medis menuntut kesabaran dan teknik perawatan khusus, bukan kekerasan."},
{id:"TKP-866", q:"Anda guru. Orang tua siswa protes karena anaknya diajari toleransi beragama yang dianggap 'menyimpang'. Sikap Anda ....", opts:[{t:"Menjelaskan bahwa toleransi adalah amanat kurikulum dan konstitusi, dengan dialog yang santun dan terbuka", s:5},{t:"Menunjukkan dasar kurikulum dan tujuan pembelajarannya", s:4},{t:"Menghentikan materi toleransi agar tidak ribut", s:3},{t:"Mengikuti kemauan orang tua yang protes", s:2},{t:"Mendebat orang tua dengan emosi", s:1}], ex:"Toleransi adalah nilai konstitusional; guru menjelaskannya dengan dialog santun berbasis aturan."},
{id:"TKP-867", q:"Anda petugas puskesmas. Mantan narapidana ingin menjadi kader kesehatan tetapi warga menolak. Sikap Anda ....", opts:[{t:"Memberinya kesempatan dengan pembinaan, mengedukasi warga tentang reintegrasi, dan mengevaluasi kinerjanya objektif", s:5},{t:"Menerimanya sebagai kader dengan pendampingan", s:4},{t:"Menolak karena tekanan warga", s:3},{t:"Menerima tetapi menyembunyikan latar belakangnya", s:2},{t:"Menolak dan mengusirnya", s:1}], ex:"Reintegrasi sosial membutuhkan kesempatan kedua yang disertai pembinaan dan evaluasi objektif."},
{id:"TKP-868", q:"Anda bidan. Suami melarang istrinya memakai KB karena alasan budaya. Sikap Anda ....", opts:[{t:"Mengedukasi pasangan tentang kesehatan reproduksi dan pilihan KB, menghormati proses keputusan mereka", s:5},{t:"Menawarkan konseling pasangan tentang jarak kelahiran yang sehat", s:4},{t:"Memaksa pemberian KB demi target program", s:3},{t:"Membiarkan tanpa edukasi", s:2},{t:"Menyalahkan suami sebagai kolot", s:1}], ex:"Edukasi yang menghormati dinamika keluarga lebih efektif daripada pemaksaan target program."},
{id:"TKP-869", q:"Anda guru. Siswa Anda menjadi korban KDRT dan prestasinya anjlok. Sikap Anda ....", opts:[{t:"Memberi dukungan emosional, menjaga kerahasiaan, dan melaporkan ke mekanisme perlindungan anak", s:5},{t:"Berkonsultasi dengan guru BK untuk penanganan", s:4},{t:"Menasihatinya agar sabar menghadapi orang tua", s:3},{t:"Menganggapnya masalah keluarga", s:2},{t:"Menyebarkan masalahnya ke guru lain sebagai gosip", s:1}], ex:"Dukungan plus pelaporan resmi adalah perlindungan ganda bagi anak korban KDRT."},
{id:"TKP-870", q:"Anda petugas kesehatan. Warga Tionghoa lansia hanya nyaman dilayani petugas yang berbahasa Mandarin/Hokkien. Sikap Anda ....", opts:[{t:"Mengupayakan petugas/kader yang bisa berkomunikasi dalam bahasanya atau alat bantu terjemahan", s:5},{t:"Meminta bantuan keluarga sebagai penerjemah", s:4},{t:"Memaksanya berbahasa Indonesia", s:3},{t:"Menunda pelayanannya", s:2},{t:"Mengejeknya sebagai tidak nasionalis", s:1}], ex:"Akomodasi bahasa memastikan lansia memahami diagnosis dan pengobatannya dengan benar."}
,
{id:"TKP-871", q:"Anda petugas rekam medis. Sistem SIMRS down dan data pasien tidak bisa diakses saat pelayanan ramai. Sikap Anda ....", opts:[{t:"Beralih ke prosedur manual darurat yang tertib, mencatat dengan rapi untuk diinput ulang, dan melaporkan gangguan ke tim IT", s:5},{t:"Menggunakan catatan kertas sementara sambil menunggu sistem pulih", s:4},{t:"Menunda pelayanan sampai sistem normal", s:3},{t:"Membiarkan pasien menunggu tanpa kejelasan", s:2},{t:"Memanfaatkan situasi untuk meminta pungutan 'percepatan'", s:1}], ex:"Prosedur darurat manual yang tertib menjaga layanan tetap berjalan saat sistem digital gagal."},
{id:"TKP-872", q:"Anda petugas P-Care BPJS. Data pasien bocor dan tersebar di media sosial. Sikap Anda ....", opts:[{t:"Segera melaporkan insiden ke atasan dan tim keamanan data, membantu investigasi, dan mengedukasi ulang tentang kerahasiaan data", s:5},{t:"Melaporkan kebocoran sesuai prosedur keamanan informasi", s:4},{t:"Menghapus postingan yang Anda temukan", s:3},{t:"Membiarkan karena bukan Anda yang membocorkan", s:2},{t:"Ikut menyebarkan data tersebut", s:1}], ex:"Respons cepat dan pelaporan resmi meminimalkan dampak kebocoran data pribadi pasien."},
{id:"TKP-873", q:"Anda guru. Siswa menyebarkan hoaks kesehatan (misal vaksin berbahaya) di grup kelas. Sikap Anda ....", opts:[{t:"Mengoreksi dengan fakta dari sumber kredibel, menjadikannya pembelajaran literasi digital, tanpa mempermalukan siswa", s:5},{t:"Menjelaskan fakta yang benar dan meminta siswa menghapus hoaksnya", s:4},{t:"Menghapus pesan tersebut tanpa penjelasan", s:3},{t:"Membiarkan karena menganggapnya sepele", s:2},{t:"Menghukum siswa dengan berat", s:1}], ex:"Koreksi faktual yang mendidik membangun literasi digital tanpa menciptakan ketakutan."},
{id:"TKP-874", q:"Anda petugas PPDB online. Sistem sering error dan orang tua mengeluh tidak bisa mendaftar. Sikap Anda ....", opts:[{t:"Membuka posko bantuan pendaftaran offline/daring, memandu orang tua, dan melaporkan kendala teknis untuk perbaikan", s:5},{t:"Membantu orang tua yang kesulitan secara manual", s:4},{t:"Menyuruh orang tua mencoba lagi nanti", s:3},{t:"Menyalahkan vendor sistem", s:2},{t:"Mengabaikan keluhan orang tua", s:1}], ex:"Posko bantuan memastikan tidak ada calon siswa yang kehilangan hak karena kegagalan teknis."},
{id:"TKP-875", q:"Anda perawat. Rekan mengunggah foto pasien (tanpa sensor) ke media sosial pribadinya. Sikap Anda ....", opts:[{t:"Mengingatkan rekan untuk menghapusnya dan melaporkan pelanggaran privasi pasien sesuai aturan", s:5},{t:"Menegur rekan dan menjelaskan risiko hukumnya", s:4},{t:"Mengabaikan karena bukan urusan Anda", s:3},{t:"Ikut mengomentari foto tersebut", s:2},{t:"Ikut menyebarkan foto pasien tersebut", s:1}], ex:"Privasi pasien dilindungi undang-undang; konten yang mengunggahnya wajib dihapus dan dilaporkan."},
{id:"TKP-876", q:"Anda guru. Saat pembelajaran daring, seorang siswa mengaktifkan kamera temannya yang sedang tidak pantas. Sikap Anda ....", opts:[{t:"Segera menghentikan, melindungi privasi siswa tersebut, dan mengedukasi kelas tentang etika digital", s:5},{t:"Menegur pelaku dan melaporkan ke wali kelas", s:4},{t:"Menertawakan kejadian tersebut", s:3},{t:"Membiarkan karena di luar kendali", s:2},{t:"Menyebarkan rekamannya", s:1}], ex:"Perlindungan privasi siswa dalam pembelajaran daring adalah tanggung jawab guru."},
{id:"TKP-877", q:"Anda petugas Dapodik. Operator sekolah meminta Anda 'memutihkan' data siswa fiktif. Sikap Anda ....", opts:[{t:"Menolak karena data fiktif merugikan negara dan melanggar hukum", s:5},{t:"Menolak dan melaporkan ke pengawas/dinas", s:4},{t:"Menunda dengan alasan sistem terkunci", s:3},{t:"Membantu karena kasihan sekolahnya", s:2},{t:"Membantu dengan imbalan", s:1}], ex:"Data pokok pendidikan yang fiktif merampok hak siswa nyata; penolakan adalah kewajiban."},
{id:"TKP-878", q:"Anda dokter. Pasien membawa hasil diagnosis dari aplikasi AI dan menuntut pengobatan sesuai saran aplikasi. Sikap Anda ....", opts:[{t:"Menghargai inisiatif pasien, menjelaskan keterbatasan AI, dan menegakkan diagnosis berdasarkan pemeriksaan klinis", s:5},{t:"Memeriksa ulang secara klinis dan menjelaskan hasilnya", s:4},{t:"Mengikuti saran aplikasi agar pasien puas", s:3},{t:"Mengejek pasien yang percaya aplikasi", s:2},{t:"Menolak memeriksa karena tersinggung", s:1}], ex:"Teknologi adalah alat bantu, bukan pengganti penilaian klinis dokter."},
{id:"TKP-879", q:"Anda petugas kesehatan. Grup WhatsApp warga menyebarkan resep obat tradisional yang berbahaya. Sikap Anda ....", opts:[{t:"Memberi klarifikasi berbasis bukti di grup dengan bahasa santun dan menawarkan konsultasi", s:5},{t:"Mengirimkan informasi resmi dari kemenkes/dinkes sebagai pembanding", s:4},{t:"Keluar dari grup agar tidak terlibat", s:3},{t:"Membiarkan karena bukan wewenang", s:2},{t:"Ikut menyebarkan agar viral", s:1}], ex:"Klarifikasi proaktif di ruang digital warga mencegah bahaya kesehatan akibat misinformasi."},
{id:"TKP-880", q:"Anda guru. Nilai digital siswa di e-rapor tidak sengaja terhapus sebelum dibackup. Sikap Anda ....", opts:[{t:"Segera melaporkan ke operator/admin, merekonstruksi dari dokumen fisik, dan memperbaiki prosedur backup", s:5},{t:"Mengumpulkan kembali data dari arsip fisik dan rekan", s:4},{t:"Mengarang nilai agar cepat selesai", s:3},{t:"Menyalahkan operator sistem", s:2},{t:"Membiarkan dan berharap tidak ketahuan", s:1}], ex:"Transparansi insiden plus rekonstruksi faktual dan perbaikan prosedur adalah respons akuntabel."},
{id:"TKP-881", q:"Anda petugas puskesmas. Seseorang menelepon mengaku keluarga pasien untuk meminta data medis via telepon. Sikap Anda ....", opts:[{t:"Menolak memberi data via telepon dan meminta verifikasi identitas resmi sesuai prosedur", s:5},{t:"Meminta surat kuasa dan identitas sebelum memberikan informasi", s:4},{t:"Memberi sebagian informasi karena kasihan", s:3},{t:"Memberi semua data yang diminta", s:2},{t:"Memberi data dengan imbalan pulsa", s:1}], ex:"Verifikasi identitas melindungi data medis dari penyalahgunaan oleh pihak tak berwenang."},
{id:"TKP-882", q:"Anda guru. Akun media sosial sekolah diretas dan memposting konten tidak pantas. Sikap Anda ....", opts:[{t:"Segera mengamankan akun, menghapus konten, mengumumkan klarifikasi resmi, dan melaporkan peretasan", s:5},{t:"Melaporkan ke admin dan membantu pemulihan akun", s:4},{t:"Menghapus postingan tanpa klarifikasi", s:3},{t:"Membiarkan sampai admin sadar", s:2},{t:"Ikut menyebarkan tangkapan layarnya sebagai lelucon", s:1}], ex:"Respons cepat, klarifikasi resmi, dan pelaporan melindungi reputasi sekolah dan warga sekolah."},
{id:"TKP-883", q:"Anda petugas telemedicine. Koneksi buruk membuat konsultasi daring terputus-putus dengan pasien di daerah terpencil. Sikap Anda ....", opts:[{t:"Beradaptasi (mode audio/chat, penjadwalan ulang), memastikan pasien tetap mendapat layanan yang memadai", s:5},{t:"Melanjutkan dengan media yang paling stabil tersedia", s:4},{t:"Membatalkan konsultasi dan menyuruh datang langsung", s:3},{t:"Membiarkan pasien menunggu tanpa kabar", s:2},{t:"Menutup layanan telemedicine", s:1}], ex:"Adaptasi media memastikan keterbatasan infrastruktur tidak memutus akses layanan."},
{id:"TKP-884", q:"Anda perawat. Ada tawaran menjual data kontak pasien ke perusahaan asuransi. Sikap Anda ....", opts:[{t:"Menolak dan melaporkan tawaran tersebut sebagai pelanggaran privasi", s:5},{t:"Menolak dengan tegas", s:4},{t:"Mempertimbangkan karena keuntungannya besar", s:3},{t:"Menjual sebagian data", s:2},{t:"Menjual seluruh data pasien", s:1}], ex:"Data pasien adalah amanah; memperjualbelikannya adalah pelanggaran etik dan hukum."},
{id:"TKP-885", q:"Anda guru. Siswa menggunakan AI untuk mengerjakan tugas dan mengaku sebagai karyanya. Sikap Anda ....", opts:[{t:"Menjadikannya momen edukasi tentang etika penggunaan AI, memberi tugas yang menilai proses, bukan sekadar hasil", s:5},{t:"Menegur dan memberi kesempatan mengerjakan ulang secara mandiri", s:4},{t:"Memberi nilai nol tanpa penjelasan", s:3},{t:"Membiarkan karena zaman sudah berubah", s:2},{t:"Melarang total teknologi di kelas", s:1}], ex:"Edukasi etika AI plus desain tugas yang menilai proses menyiapkan siswa menghadapi era digital secara jujur."},
{id:"TKP-886", q:"Anda petugas arsip RSUD. Dokumen fisik rekam medis menumpuk dan sebagian rusak. Sikap Anda ....", opts:[{t:"Mengusulkan dan menjalankan digitalisasi bertahap dengan prioritas dokumen aktif, sesuai aturan retensi arsip", s:5},{t:"Memilah dan mengamankan dokumen penting terlebih dahulu", s:4},{t:"Membiarkan menumpuk karena keterbatasan anggaran", s:3},{t:"Membuang dokumen lama tanpa prosedur", s:2},{t:"Membakar arsip agar gudang kosong", s:1}], ex:"Digitalisasi bertahap sesuai aturan retensi menyelamatkan data sekaligus menertibkan arsip."},
{id:"TKP-887", q:"Anda petugas kesehatan. Aplikasi antrean online puskesmas disalahgunakan calo yang menjual nomor antrean. Sikap Anda ....", opts:[{t:"Melaporkan ke tim IT untuk perbaikan sistem (verifikasi identitas) dan menindak calo sesuai aturan", s:5},{t:"Mengusulkan sistem verifikasi NIK saat pendaftaran", s:4},{t:"Membiarkan karena sulit dibuktikan", s:3},{t:"Ikut menjadi calo", s:2},{t:"Meminta jatah dari calo", s:1}], ex:"Perbaikan sistem plus penindakan memberantas percaloan yang merugikan pasien."},
{id:"TKP-888", q:"Anda guru. Orang tua memprotes nilai anaknya via media sosial dan memviralkan nama Anda. Sikap Anda ....", opts:[{t:"Tetap tenang, tidak membalas di medsos, dan mengundang orang tua berdialog resmi dengan data penilaian", s:5},{t:"Melaporkan ke kepala sekolah untuk mediasi resmi", s:4},{t:"Membalas dengan emosi di media sosial", s:3},{t:"Mengancam balik orang tua tersebut", s:2},{t:"Mengubah nilai agar viralnya berhenti", s:1}], ex:"Tidak terpancing di ruang publik dan menawarkan dialog berbasis data menjaga martabat profesi."},
{id:"TKP-889", q:"Anda petugas lab. Hasil tes cepat (rapid test) massal akan diumumkan dan ada tekanan memanipulasi angka. Sikap Anda ....", opts:[{t:"Menolak manipulasi dan mengumumkan data apa adanya sesuai hasil pemeriksaan", s:5},{t:"Melaporkan tekanan tersebut ke atasan/pengawas", s:4},{t:"Menunda pengumuman dengan alasan teknis", s:3},{t:"Mengubah angka sesuai tekanan", s:2},{t:"Mengubah angka dengan imbalan", s:1}], ex:"Data kesehatan publik yang jujur adalah dasar kebijakan yang tepat; manipulasi membahayakan masyarakat."},
{id:"TKP-890", q:"Anda dokter. Pasien merekam konsultasi tanpa izin dan mengancam menyebarkannya jika tidak diberi rujukan. Sikap Anda ....", opts:[{t:"Tetap tenang, tidak tunduk pada ancaman, menjelaskan prosedur rujukan, dan melaporkan pemerasan sesuai aturan", s:5},{t:"Menolak ancaman dan meminta ia menempuh jalur pengaduan resmi", s:4},{t:"Memberi rujukan agar masalah selesai", s:3},{t:"Mengancam balik pasien", s:2},{t:"Memukul pasien yang merekam", s:1}], ex:"Tidak tunduk pada pemerasan sambil menawarkan jalur resmi melindungi integritas layanan."}
,
{id:"TKP-891", q:"Anda guru. Seorang siswa menyebarkan konten ceramah provokatif yang menghasut kebencian antaragama di grup kelas. Sikap Anda ....", opts:[{t:"Segera menghentikan penyebaran, mengedukasi tentang bahaya ujaran kebencian, dan melaporkan sesuai mekanisme sekolah", s:5},{t:"Menghapus konten dan membina siswa tersebut", s:4},{t:"Menasihati siswa agar tidak menyebarkan lagi", s:3},{t:"Membiarkan karena menganggapnya kebebasan berpendapat", s:2},{t:"Ikut menyebarkan karena sependapat", s:1}], ex:"Respons cepat plus edukasi mencegah radikalisasi di lingkungan sekolah."},
{id:"TKP-892", q:"Anda guru. Rekan guru terindikasi menyisipkan paham ekstrem dalam pembelajaran. Sikap Anda ....", opts:[{t:"Melaporkan indikasi tersebut ke kepala sekolah/pengawas melalui jalur resmi dengan bukti", s:5},{t:"Berdiskusi dengan kepala sekolah tentang temuan Anda", s:4},{t:"Menasihati rekan tersebut secara pribadi", s:3},{t:"Diam karena takut difitnah balik", s:2},{t:"Ikut menyebarkan paham tersebut", s:1}], ex:"Pelaporan resmi atas indikasi radikalisasi di kalangan pendidik melindungi peserta didik."},
{id:"TKP-893", q:"Anda petugas puskesmas. Di ruang tunggu, seseorang berceramah mengajak menolak program pemerintah karena dianggap 'thaghut'. Sikap Anda ....", opts:[{t:"Menegur dengan sopan, menegaskan fasilitas kesehatan netral dari propaganda, dan melaporkan bila berlanjut", s:5},{t:"Meminta yang bersangkutan menghentikan ceramahnya", s:4},{t:"Membiarkan karena menghargai kebebasan berpendapat", s:3},{t:"Ikut mendengarkan dan terpengaruh", s:2},{t:"Ikut menyebarkan ajakannya", s:1}], ex:"Fasilitas publik harus steril dari propaganda ekstrem; ketegasan sopan menjaga kenyamanan semua."},
{id:"TKP-894", q:"Anda pembina OSIS. Ada usulan kegiatan keagamaan yang eksklusif dan menolak melibatkan siswa berbeda keyakinan. Sikap Anda ....", opts:[{t:"Mengarahkan kegiatan yang inklusif dan menghormati keberagaman, sesuai semangat Bhinneka Tunggal Ika", s:5},{t:"Memfasilitasi dialog agar kegiatan tidak eksklusif", s:4},{t:"Menyetujui karena mayoritas menghendaki", s:3},{t:"Membiarkan siswa mengatur sendiri", s:2},{t:"Mendukung eksklusivitas tersebut", s:1}], ex:"Pembinaan kesiswaan yang inklusif mencegah bibit intoleransi sejak dini."},
{id:"TKP-895", q:"Anda guru. Siswa Anda direkrut ke kelompok kajian tertutup yang mengajarkan penolakan terhadap Pancasila. Sikap Anda ....", opts:[{t:"Melaporkan ke kepala sekolah dan berkoordinasi dengan orang tua serta pihak berwenang sesuai prosedur", s:5},{t:"Membina siswa dengan penguatan wawasan kebangsaan", s:4},{t:"Menasihati siswa agar keluar dari kelompok tersebut", s:3},{t:"Menganggapnya masalah keluarga", s:2},{t:"Membiarkan karena bukan urusan sekolah", s:1}], ex:"Rekrutmen radikal pada pelajar wajib direspons sistemik: sekolah, keluarga, dan aparat."},
{id:"TKP-896", q:"Anda petugas kesehatan. Pasien menolak ditangani petugas berbeda agama dengan alasan keyakinan ekstrem. Sikap Anda ....", opts:[{t:"Menjelaskan profesionalisme tenaga kesehatan, menawarkan solusi yang wajar, tanpa membenarkan diskriminasi", s:5},{t:"Mengatur ulang petugas bila memungkinkan sambil mengedukasi", s:4},{t:"Langsung mengganti petugas sesuai permintaan", s:3},{t:"Membiarkan pasien tanpa penanganan", s:2},{t:"Membenarkan penolakannya", s:1}], ex:"Akomodasi wajar tanpa menormalisasi diskriminasi menjaga prinsip kesetaraan layanan."},
{id:"TKP-897", q:"Anda guru. Menjelang pemilu, ada siswa yang mengkampanyekan calon dengan ujaran kebencian SARA di sekolah. Sikap Anda ....", opts:[{t:"Menindak sesuai tata tertib, mengedukasi tentang pemilu damai, dan melaporkan bila melanggar hukum", s:5},{t:"Menghentikan kampanye dan membina siswa tersebut", s:4},{t:"Membiarkan karena bagian dari pembelajaran demokrasi", s:3},{t:"Mendukung calon yang dikampanyekan siswa", s:2},{t:"Ikut menyebarkan ujaran kebenciannya", s:1}], ex:"Sekolah harus bebas dari politik SARA; edukasi demokrasi damai adalah tugas pendidik."},
{id:"TKP-898", q:"Anda perawat. Keluarga pasien menyebarkan teori konspirasi bahwa RS sengaja 'mengcovidkan' pasien. Sikap Anda ....", opts:[{t:"Menjelaskan prosedur medis dengan transparan dan sabar, menunjukkan data, tanpa terpancing emosi", s:5},{t:"Memberi penjelasan medis yang faktual", s:4},{t:"Membiarkan karena sulit diubah", s:3},{t:"Berempati berlebihan hingga meragukan prosedur sendiri", s:2},{t:"Ikut menyebarkan teori konspirasi", s:1}], ex:"Transparansi dan kesabaran menjelaskan adalah antidot misinformasi di fasilitas kesehatan."},
{id:"TKP-899", q:"Anda petugas dinas pendidikan. Ditemukan buku ajar bermuatan intoleransi beredar di sekolah. Sikap Anda ....", opts:[{t:"Menarik peredarannya, melaporkan ke pengawas, dan memastikan diganti materi yang sesuai kurikulum", s:5},{t:"Melaporkan temuan ke atasan untuk tindak lanjut", s:4},{t:"Membiarkan karena sudah telanjur dibagikan", s:3},{t:"Menganggapnya perbedaan tafsir biasa", s:2},{t:"Ikut menyebarkan buku tersebut", s:1}], ex:"Materi ajar intoleran harus ditarik; kurikulum wajib menanamkan persatuan."},
{id:"TKP-900", q:"Anda guru. Alumni mengajak siswa bergabung ormas yang rekam jejaknya anarkis dan intoleran. Sikap Anda ....", opts:[{t:"Mengedukasi siswa tentang rekam jejak ormas tersebut, memperkuat wawasan kebangsaan, dan melaporkan perekrutan ke sekolah", s:5},{t:"Memperingatkan siswa dan berkoordinasi dengan orang tua", s:4},{t:"Menasihati siswa agar hati-hati", s:3},{t:"Membiarkan karena urusan di luar sekolah", s:2},{t:"Mendukung ajakan alumni tersebut", s:1}], ex:"Perlindungan siswa dari perekrutan ormas bermasalah adalah tanggung jawab pendidik."}
];
